function stripAccentsKeepEnye(s) {
  return String(s || "")
    .replace(/[ÁÀÄÂ]/g, "A")
    .replace(/[ÉÈËÊ]/g, "E")
    .replace(/[ÍÌÏÎ]/g, "I")
    .replace(/[ÓÒÖÔ]/g, "O")
    .replace(/[ÚÙÜÛ]/g, "U")
    .replace(/[áàäâ]/g, "a")
    .replace(/[éèëê]/g, "e")
    .replace(/[íìïî]/g, "i")
    .replace(/[óòöô]/g, "o")
    .replace(/[úùüû]/g, "u");
}

function norm(s) {
  const t = String(s || "").trim();
  if (!t) return "";
  const up = stripAccentsKeepEnye(t).toUpperCase();
  return up.replace(/[\r\n\t]+/g, " ").replace(/\s{2,}/g, " ").trim();
}

function escapeRegExp(str) {
  return String(str || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function containsWordOrPhrase(haystack, needle) {
  if (!needle) return false;
  const n = needle.trim();
  if (!n) return false;
  if (/\s/.test(n)) return haystack.includes(n);
  const re = new RegExp(`(^|[^A-Z0-9Ñ])${escapeRegExp(n)}($|[^A-Z0-9Ñ])`, "i");
  return re.test(haystack);
}

function appendObs(oldObs, line) {
  const base = String(oldObs || "").trim();
  const add = String(line || "").trim();
  if (!add) return base;
  if (!base) return add;
  if (base.includes(add)) return base;
  return base + "\n" + add;
}

function isBlank(v) {
  return !String(v ?? "").trim();
}

const items = $input.all();
const now = new Date().toISOString();

for (const item of items) {
  const j = item.json || {};

  const tieneTexto = String(j.TIENE_TEXTO || "").toUpperCase().trim() === "SI";
  const numImgs = Number(j.NUM_IMAGENES || 0);
  const imgUrls = String(j.IMG_URLS || "").trim();
  const tieneImagenesReales = numImgs > 0 && imgUrls !== "";

  const tieneVideo = String(j.TIENE_VIDEO || "").toUpperCase().trim() === "SI";
  const url = String(j.POST_URL || "");
  const esReel = url.includes("/reel/") || url.includes("facebook.com/reel");

  // ══════════════════════════════════════════════════════════════════
  // CASO 0: SIN TEXTO - clasificar directamente sin diccionario
  // ══════════════════════════════════════════════════════════════════
  if (!tieneTexto) {
    if (isBlank(j.FASE2_STATUS)) {
      if (esReel) {
        j.FASE2_STATUS = "FASE10_VIDEOSINPROCESAR";
        j.FASE2_RUN_AT = now;
        j.FASE2_NOTAS = "AUTO: es reel sin texto -> FASE10";
        j.OBSERVACIONES_DRAMATICOS = appendObs(j.OBSERVACIONES_DRAMATICOS, "FASE10: REEL SIN TEXTO");
      } else if (tieneVideo) {
        j.FASE2_STATUS = "FASE10_VIDEOSINPROCESAR";
        j.FASE2_RUN_AT = now;
        j.FASE2_NOTAS = "AUTO: tiene video sin texto -> FASE10";
        j.OBSERVACIONES_DRAMATICOS = appendObs(j.OBSERVACIONES_DRAMATICOS, "FASE10: VIDEO SIN TEXTO");
      } else if (tieneImagenesReales) {
        j.FASE2_STATUS = "PEND_IMG_NO_MATCH";
        j.FASE2_RUN_AT = now;
        j.FASE2_NOTAS = "AUTO: sin texto pero con imagenes -> pendiente IMG";
        j.OBSERVACIONES_DRAMATICOS = appendObs(j.OBSERVACIONES_DRAMATICOS, "PEND_IMG: SIN TEXTO CON IMAGENES");
      } else {
        j.FASE2_STATUS = "DESCARTADO_SIN_CONTENIDO";
        j.FASE2_RUN_AT = now;
        j.FASE2_NOTAS = "AUTO: sin texto, sin imagenes, sin video -> descartado";
        j.OBSERVACIONES_DRAMATICOS = appendObs(j.OBSERVACIONES_DRAMATICOS, "DESCARTADO: SIN CONTENIDO UTIL");
      }
    }
    continue;
  }

  // ══════════════════════════════════════════════════════════════════
  // CASO 1+: CON TEXTO - usar diccionario de etiquetas
  // ══════════════════════════════════════════════════════════════════
  const dic = Array.isArray(j.__DIC_ETIQUETAS) ? j.__DIC_ETIQUETAS : [];
  const nombre = norm(j.NOMBRE_EVENTO);
  const texto = norm(j.TEXTO_POST);
  const matches = [];

  for (const row of dic) {
    const etiqueta = norm(row.ETIQUETA || row.Etiqueta || row.etiqueta);
    const tipo = norm(row.TIPO_EVENTO || row.Tipo_Evento || row.tipo_evento);
    const prioRaw = row.PRIORIDAD ?? row.Prioridad ?? row.prioridad;
    const prioridad = Number(prioRaw);

    if (!etiqueta || !Number.isFinite(prioridad)) continue;

    const sinRaw = String(row.SINONIMOS || row.Sinonimos || row.sinonimos || "").trim();
    if (!sinRaw) continue;

    const synonyms = sinRaw.split(";").map(s => norm(s)).filter(Boolean);
    if (!synonyms.length) continue;

    let foundIn = "";
    let foundToken = "";

    for (const syn of synonyms) {
      if (nombre && containsWordOrPhrase(nombre, syn)) {
        foundIn = "NOMBRE";
        foundToken = syn;
        break;
      }
    }

    if (!foundIn) {
      for (const syn of synonyms) {
        if (texto && containsWordOrPhrase(texto, syn)) {
          foundIn = "TEXTO";
          foundToken = syn;
          break;
        }
      }
    }

    if (foundIn) {
      matches.push({
        ETIQUETA: etiqueta,
        TIPO_EVENTO: tipo,
        PRIORIDAD: prioridad,
        FOUND_IN: foundIn,
        TOKEN: foundToken,
        TOKEN_LEN: foundToken.length,
      });
    }
  }

  matches.sort((a, b) => {
    if (a.PRIORIDAD !== b.PRIORIDAD) return a.PRIORIDAD - b.PRIORIDAD;
    return (b.TOKEN_LEN || 0) - (a.TOKEN_LEN || 0);
  });

  const best = matches[0] || null;

  if (!best) {
    // NO MATCH
    if (isBlank(j.FASE2_STATUS)) {
      if (esReel) {
        j.FASE2_STATUS = "FASE10_VIDEOSINPROCESAR";
        j.FASE2_RUN_AT = now;
        j.FASE2_NOTAS = "AUTO: es reel sin match -> FASE10";
        j.OBSERVACIONES_DRAMATICOS = appendObs(j.OBSERVACIONES_DRAMATICOS, "FASE10: REEL (NO MATCH)");
      } else if (tieneVideo) {
        j.FASE2_STATUS = "FASE10_VIDEOSINPROCESAR";
        j.FASE2_RUN_AT = now;
        j.FASE2_NOTAS = "AUTO: tiene video sin match -> FASE10";
        j.OBSERVACIONES_DRAMATICOS = appendObs(j.OBSERVACIONES_DRAMATICOS, "FASE10: VIDEO (NO MATCH)");
      } else if (tieneImagenesReales) {
        j.FASE2_STATUS = "PEND_IMG_NO_MATCH";
        j.FASE2_RUN_AT = now;
        j.FASE2_NOTAS = "AUTO: sin match por nombre/texto, tiene imagenes";
        j.OBSERVACIONES_DRAMATICOS = appendObs(j.OBSERVACIONES_DRAMATICOS, "PEND_IMG: NO_MATCH CON IMAGENES");
      } else {
        j.FASE2_STATUS = "DESCARTADO_SIN_IMAGENES";
        j.FASE2_RUN_AT = now;
        j.FASE2_NOTAS = "AUTO: sin match, sin imagenes, sin video -> descartado";
        j.OBSERVACIONES_DRAMATICOS = appendObs(j.OBSERVACIONES_DRAMATICOS, "DESCARTADO: NO MATCH SIN MEDIA");
      }
    }
  } else {
    const samePrio = matches.filter(m => m.PRIORIDAD === best.PRIORIDAD);
    const uniqueEtiquetas = [...new Set(samePrio.map(m => m.ETIQUETA))];

    if (uniqueEtiquetas.length > 1) {
      // AMBIGUO
      if (isBlank(j.FASE2_STATUS)) {
        if (tieneImagenesReales) {
          j.FASE2_STATUS = "PEND_IMG_AMBIGUO";
          j.FASE2_RUN_AT = now;
          j.FASE2_NOTAS = "AUTO: ambigüedad (misma prioridad), tiene imagenes";
          j.OBSERVACIONES_DRAMATICOS = appendObs(j.OBSERVACIONES_DRAMATICOS, "PEND_IMG: AMBIGUO CON IMAGENES");
        } else if (esReel || tieneVideo) {
          j.FASE2_STATUS = "FASE10_VIDEOSINPROCESAR";
          j.FASE2_RUN_AT = now;
          j.FASE2_NOTAS = "AUTO: ambiguo + video/reel sin imagenes -> FASE10";
          j.OBSERVACIONES_DRAMATICOS = appendObs(j.OBSERVACIONES_DRAMATICOS, "FASE10: AMBIGUO VIDEO/REEL");
        } else {
          j.FASE2_STATUS = "PEND_IMG_AMBIGUO";
          j.FASE2_RUN_AT = now;
          j.FASE2_NOTAS = "AUTO: ambigüedad (misma prioridad)";
          j.OBSERVACIONES_DRAMATICOS = appendObs(j.OBSERVACIONES_DRAMATICOS, "PEND_IMG: AMBIGUO");
        }
      }
    } else {
      // RESUELTO
      j.ETIQUETAS = best.ETIQUETA;
      j.TIPO_EVENTO = best.TIPO_EVENTO || "";
      j.OBSERVACIONES_DRAMATICOS = appendObs(
        j.OBSERVACIONES_DRAMATICOS,
        `FASE2_OK(${best.FOUND_IN}): ${best.ETIQUETA} -> ${best.TIPO_EVENTO} [${best.TOKEN}]`
      );

      if (isBlank(j.FASE2_STATUS)) {
        j.FASE2_STATUS = "OK_TEXTO";
        j.FASE2_RUN_AT = now;
        j.FASE2_NOTAS = `AUTO: resuelto por ${best.FOUND_IN} [${best.TOKEN}]`;
      }
    }
  }

  // Paracaídas anti-blancos
  if (isBlank(j.FASE2_STATUS)) {
    j.FASE2_STATUS = "FASE2_SIN_CLASIFICAR";
    j.FASE2_RUN_AT = now;
    j.FASE2_NOTAS = "AUTO: fallback (no se asigno status)";
    j.OBSERVACIONES_DRAMATICOS = appendObs(j.OBSERVACIONES_DRAMATICOS, "FASE2: FALLBACK");
  }
}

return items;

// Code: Inyectar DIC_ETIQUETAS en Posts (SIN MERGE)
// Lee:
// - Posts desde "Sheets: Read FB_POSTS_RAW"
// - Diccionario empaquetado desde "Code: DIC -> 1 item"
// Devuelve SIEMPRE los posts (no colapsa a 1).

function appendObs(oldObs, line) {
  const base = String(oldObs || "").trim();
  const add = String(line || "").trim();
  if (!add) return base;
  if (!base) return add;
  if (base.includes(add)) return base;
  return base + "\n" + add;
}

const posts = $items("Sheets: Read FB_POSTS_RAW");     // <- 432
const dicPack = $items("Code: DIC -> 1 item");         // <- 1

const dic =
  (dicPack?.[0]?.json?.__DIC_ETIQUETAS && Array.isArray(dicPack[0].json.__DIC_ETIQUETAS))
    ? dicPack[0].json.__DIC_ETIQUETAS
    : [];

const ERR_LINE = "FASE2_ERROR: DIC_ETIQUETAS_VACIO (REVISA READ DIC_ETIQUETAS)";

for (const it of posts) {
  it.json.__DIC_ETIQUETAS = dic;
  it.json.__DIC_COUNT = dic.length;

  if (!dic.length) {
    it.json.OBSERVACIONES_DRAMATICOS = appendObs(it.json.OBSERVACIONES_DRAMATICOS, ERR_LINE);
  } else {
    // si antes metiste el error, lo puedes limpiar si quieres (opcional)
    const obs = String(it.json.OBSERVACIONES_DRAMATICOS || "");
    it.json.OBSERVACIONES_DRAMATICOS = obs
      .split("\n")
      .map(s => s.trim())
      .filter(s => s && s !== ERR_LINE)
      .join("\n");
  }
}

return posts;

// Convierte N filas del diccionario en 1 solo item con __DIC_ETIQUETAS = [..]
const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length);

return [
  {
    json: {
      __DIC_ETIQUETAS: rows,
      __DIC_COUNT: rows.length,
    },
  },
];

// Code: Filter Pendientes Fase (CORREGIDO, SAFE)
// - Devuelve posts pendientes
// - Si no hay, devuelve 1 item CONTROL para que el flujo siga
//   PERO marcado como __CONTROL + __SKIP_UPDATE para que nunca escriba en Sheets

const items = $input.all();
const out = [];

for (const item of items) {
  item.json.__FASE2 = item.json.__FASE2 || {};

  const estado = String(item.json.ESTADO_POST || "").trim();
  const fase2 = String(item.json.FASE2_STATUS || "").trim();

  const pendiente = (estado === "RAW") && (fase2 === "");
  if (pendiente) out.push(item);
}

if (!out.length) {
  return [{
    json: {
      __CONTROL: true,
      __CONTROL_REASON: "NO_PENDIENTES_FASE2",
      __NO_PENDIENTES: true,
      __SKIP_UPDATE: true,
      __COUNT_IN: items.length
    }
  }];
}

return out;

// MARK: REPOST_SINTEXTO_SINIMAGENES (solo para items reales)

function appendObs(oldObs, line) {
  const base = String(oldObs ?? '').trim();
  const add = String(line ?? '').trim();
  if (!add) return base;
  if (!base) return add;
  if (base.includes(add)) return base;
  return base + '\n' + add;
}

const now = new Date().toISOString();
const items = $input.all();

for (const item of items) {
  const j = item.json || {};

  // Control: no tocar
  if (j.__NO_REPOSTS === true) continue;

  const idk = String(j.IDEMPOT_KEY ?? '').trim();
  if (!idk) {
    j.__SKIP_UPDATE = true;
    j.OBSERVACIONES_DRAMATICOS = appendObs(
      j.OBSERVACIONES_DRAMATICOS,
      'FASE2_ERROR: SIN IDEMPOT_KEY (NO MARCAR REPOST)'
    );
    continue;
  }

  j.FASE2_STATUS = 'REPOST_SINTEXTO_SINIMAGENES';
  j.FASE2_RUN_AT = now;
  j.FASE2_NOTAS = 'AUTO: REPOST O SIN CONTENIDO (SIN TEXTO, SIN IMGS, SIN VIDEO)';
  j.OBSERVACIONES_DRAMATICOS = appendObs(
    j.OBSERVACIONES_DRAMATICOS,
    'FASE2_FIN: REPOST_SINTEXTO_SINIMAGENES'
  );
}

return items;

// FILTER: REPOST_SINTEXTO_SINIMAGENES (SIEMPRE DEVUELVE SALIDA)
// - Si hay matches -> devuelve matches
// - Si no hay -> devuelve 1 item CONTROL (__NO_REPOSTS) para que el flujo siga
//   y ademas __SKIP_UPDATE=true para que JAMAS llegue a Sheets.

const items = $input.all();
const out = [];

function norm(v) {
  return String(v ?? '').trim().toUpperCase();
}

for (const item of items) {
  const j = item.json || {};

  const tieneTexto = norm(j.TIENE_TEXTO);
  const tieneVideo = norm(j.TIENE_VIDEO);

  const raw = String(j.NUM_IMAGENES ?? '').trim();
  const n = Number(raw);
  const numImagenes = Number.isFinite(n) ? n : 0;

  const idk = String(j.IDEMPOT_KEY ?? '').trim();

  const esRepost =
    tieneTexto === 'NO' &&
    tieneVideo === 'NO' &&
    numImagenes === 0 &&
    idk !== '';

  if (esRepost) out.push(item);
}

if (!out.length) {
  return [{
    json: {
      __NO_REPOSTS: true,
      __SKIP_UPDATE: true,
      __COUNT_IN: items.length
    }
  }];
}

return out;

