// FILTRO FASE 1 — SOLO eventos sin NOMBRE_EVENTO
// No filtra por ayuntamiento, estado ni nada más

function isEmpty(v) {
  return v === null ||
         v === undefined ||
         (typeof v === 'string' && v.trim() === '');
}

const out = [];

for (const item of items) {
  const r = item.json || {};

  if (isEmpty(r.NOMBRE_EVENTO)) {
    out.push({ json: r });
  }
}

return out;

/**
 * n8n Code node (JavaScript)
 * ✅ Procesa TODOS los items ($input.all())
 * ✅ NO inventa: solo usa evidencia del texto/título/post
 * ✅ Relativos: hoy/mañana/ayer/pasado mañana/anteayer
 * ✅ Weekday solo ("domingo a las 12:00h") => próximo domingo (anclado al post)
 * ✅ Fechas explícitas: "30 de diciembre (de 2025)" y "30/12/2025"
 * ✅ Hora: 12:00 / 12:00h / 12:00H / 12.00 / 12h30
 */

function stripAccentsKeepEnye(s) {
  if (s === null || s === undefined) return "";
  let str = String(s);
  str = str.replace(/ñ/g, "__ENYE__").replace(/Ñ/g, "__ENYE_UP__");
  str = str.normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  str = str.replace(/__ENYE__/g, "ñ").replace(/__ENYE_UP__/g, "Ñ");
  return str;
}
function slugClean(s) {
  return stripAccentsKeepEnye(s)
    .toLowerCase()
    .trim()
    .replace(/['"]/g, "")
    .replace(/[^a-z0-9ñ]+/g, "_")
    .replace(/_+/g, "_")
    .replace(/^_+|_+$/g, "");
}
function pickFirstNonEmpty(...vals) {
  for (const v of vals) {
    if (v !== undefined && v !== null && String(v).trim() !== "") return v;
  }
  return "";
}
function safeJsonParse(s) {
  if (!s) return null;
  try { return JSON.parse(s); } catch { return null; }
}

// Convierte input a Date (ISO, timestamp seg/ms, dd/mm/yyyy)
function toDate(dateInput) {
  if (!dateInput) return null;
  if (dateInput instanceof Date && !isNaN(dateInput.getTime())) return dateInput;

  if (typeof dateInput === "number") {
    const ms = dateInput < 2e12 ? dateInput * 1000 : dateInput;
    const d = new Date(ms);
    return isNaN(d.getTime()) ? null : d;
  }

  const s = String(dateInput).trim();
  if (!s) return null;

  if (/^\d{10,13}$/.test(s)) return toDate(Number(s));

  // dd/mm/yyyy (opcional hora)
  const mES = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})(?:\s+(\d{1,2}):(\d{2}))?$/);
  if (mES) {
    const dd = Number(mES[1]), mm = Number(mES[2]), yyyy = Number(mES[3]);
    const hh = mES[4] ? Number(mES[4]) : 0;
    const min = mES[5] ? Number(mES[5]) : 0;
    const d = new Date(Date.UTC(yyyy, mm - 1, dd, hh, min, 0));
    return isNaN(d.getTime()) ? null : d;
  }

  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}

function dateToPartsUTC(d) {
  if (!d || isNaN(d.getTime())) return null;
  const yyyy = String(d.getUTCFullYear());
  const mm = String(d.getUTCMonth() + 1).padStart(2, "0");
  const dd = String(d.getUTCDate()).padStart(2, "0");
  const hh = String(d.getUTCHours()).padStart(2, "0");
  const min = String(d.getUTCMinutes()).padStart(2, "0");
  return { yyyy, mm, dd, hh, min };
}
function fmtISODate(parts) { return parts ? `${parts.yyyy}-${parts.mm}-${parts.dd}` : ""; }
function fmtESDate(parts)  { return parts ? `${parts.dd}/${parts.mm}/${parts.yyyy}` : ""; }
function fmtHM(parts)      { return parts ? `${parts.hh}:${parts.min}` : ""; }

/**
 * Hora conservadora:
 * - 20:30 / 8:05
 * - 20.30 / 8.05
 * - 8h30
 * - 12:00H (H mayúscula)
 * NO "a las 8" (sin minutos)
 */
function extractHourFromText(text) {
  const t = String(text || "");
  if (!t.trim()) return "";

  // 12:00 / 12:00h / 12:00H
  let m = t.match(/\b([01]?\d|2[0-3])\s*:\s*([0-5]\d)\s*[hH]?\b/);
  if (m) return `${String(m[1]).padStart(2, "0")}:${m[2]}`;

  // 12.00 / 12.00H
  m = t.match(/\b([01]?\d|2[0-3])\s*\.\s*([0-5]\d)\s*[hH]?\b/);
  if (m) return `${String(m[1]).padStart(2, "0")}:${m[2]}`;

  // 12h30
  m = t.match(/\b([01]?\d|2[0-3])[hH]([0-5]\d)\b/);
  if (m) return `${String(m[1]).padStart(2, "0")}:${m[2]}`;

  return "";
}

/**
 * Fecha explícita dd/mm/yyyy (en título o texto)
 */
function explicitDDMMYYYY(text) {
  const t = String(text || "");
  const m = t.match(/\b(\d{1,2})\/(\d{1,2})\/(\d{4})\b/);
  if (!m) return null;
  const dd = Number(m[1]), mm = Number(m[2]), yyyy = Number(m[3]);
  if (dd < 1 || dd > 31 || mm < 1 || mm > 12) return null;
  const d = new Date(Date.UTC(yyyy, mm - 1, dd, 0, 0, 0));
  return isNaN(d.getTime()) ? null : d;
}

/**
 * Fechas explícitas:
 * "30 de diciembre" / "martes, 30 de diciembre" / "30 de diciembre de 2025"
 * Si no hay año, usa año del post.
 */
function explicitSpanishDateFromText(text, anchorDate) {
  const t0 = String(text || "");
  if (!t0.trim()) return null;

  const t = stripAccentsKeepEnye(t0.toLowerCase());

  const monthMap = {
    enero: 1, febrero: 2, marzo: 3, abril: 4, mayo: 5, junio: 6,
    julio: 7, agosto: 8, septiembre: 9, setiembre: 9, octubre: 10, noviembre: 11, diciembre: 12,
  };

  const re = /\b(?:lunes|martes|miercoles|jueves|viernes|sabado|domingo)?\s*,?\s*(\d{1,2})\s*de\s*(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|setiembre|octubre|noviembre|diciembre)(?:\s*de\s*(\d{4}))?\b/;
  const m = t.match(re);
  if (!m) return null;

  const dd = Number(m[1]);
  const mm = monthMap[m[2]];
  if (!mm || dd < 1 || dd > 31) return null;

  let yyyy = m[3] ? Number(m[3]) : null;
  if (!yyyy) {
    if (!anchorDate || isNaN(anchorDate.getTime())) return null;
    yyyy = anchorDate.getUTCFullYear();
  }

  const d = new Date(Date.UTC(yyyy, mm - 1, dd, 0, 0, 0));
  return isNaN(d.getTime()) ? null : d;
}

const weekdayMap = {
  lunes: 1, martes: 2, miercoles: 3, jueves: 4, viernes: 5, sabado: 6, domingo: 0,
};
function nextWeekdayFromAnchor(anchorDate, targetDow, includeToday = false) {
  if (!anchorDate || isNaN(anchorDate.getTime())) return null;
  const base = new Date(Date.UTC(anchorDate.getUTCFullYear(), anchorDate.getUTCMonth(), anchorDate.getUTCDate(), 0, 0, 0));
  const currentDow = base.getUTCDay(); // 0 domingo
  let delta = (targetDow - currentDow + 7) % 7;
  if (delta === 0 && !includeToday) delta = 7;
  base.setUTCDate(base.getUTCDate() + delta);
  return base;
}

/**
 * Relativos:
 * - hoy/mañana/ayer/pasado mañana/anteayer
 * - "mañana domingo" / "este domingo" / "próximo domingo"
 * - NUEVO: "domingo a las 12:00" (weekday solo) => próximo domingo (anclado al post)
 * NO usa "esta mañana/tarde/noche" como fecha de evento.
 */
function relativeDateFromText(text, anchorDate) {
  const t0 = String(text || "");
  if (!t0.trim()) return null;
  if (!anchorDate || isNaN(anchorDate.getTime())) return null;

  const t = stripAccentsKeepEnye(t0.toLowerCase());

  // 0) No considerar "esta mañana/tarde/noche" como fecha de evento
  if (/\besta\s+(manana|tarde|noche|madrugada)\b/.test(t)) {
    // No devolvemos nada: NO es evidencia de fecha de evento
    // (si luego hay otra evidencia en el texto, se capturará por otras reglas)
  }

  // 1) Relativo con weekday explícito (mañana domingo, este domingo, próximo domingo...)
  const mW = t.match(/\b(manana|hoy|ayer|pasado\s+manana|anteayer|este|esta|proximo|proxima)\s+(lunes|martes|miercoles|jueves|viernes|sabado|domingo)\b/);
  if (mW) {
    const rel = mW[1].replace(/\s+/g, " ").trim();
    const wd = mW[2];
    const targetDow = weekdayMap[wd];

    if (rel === "manana") {
      const tomorrow = new Date(Date.UTC(anchorDate.getUTCFullYear(), anchorDate.getUTCMonth(), anchorDate.getUTCDate(), 0, 0, 0));
      tomorrow.setUTCDate(tomorrow.getUTCDate() + 1);
      if (tomorrow.getUTCDay() === targetDow) return tomorrow;
      return nextWeekdayFromAnchor(anchorDate, targetDow, false);
    }

    if (rel === "hoy") {
      const today = new Date(Date.UTC(anchorDate.getUTCFullYear(), anchorDate.getUTCMonth(), anchorDate.getUTCDate(), 0, 0, 0));
      return (today.getUTCDay() === targetDow) ? today : nextWeekdayFromAnchor(anchorDate, targetDow, false);
    }

    if (rel === "ayer") {
      const y = new Date(Date.UTC(anchorDate.getUTCFullYear(), anchorDate.getUTCMonth(), anchorDate.getUTCDate(), 0, 0, 0));
      y.setUTCDate(y.getUTCDate() - 1);
      return y;
    }

    if (rel === "pasado manana") {
      const pm = new Date(Date.UTC(anchorDate.getUTCFullYear(), anchorDate.getUTCMonth(), anchorDate.getUTCDate(), 0, 0, 0));
      pm.setUTCDate(pm.getUTCDate() + 2);
      return pm;
    }

    if (rel === "anteayer") {
      const a = new Date(Date.UTC(anchorDate.getUTCFullYear(), anchorDate.getUTCMonth(), anchorDate.getUTCDate(), 0, 0, 0));
      a.setUTCDate(a.getUTCDate() - 2);
      return a;
    }

    // "este/proximo <weekday>" -> siguiente ocurrencia (no hoy)
    return nextWeekdayFromAnchor(anchorDate, targetDow, false);
  }

  // 2) Relativos simples (sin weekday)
  if (/\bpasado\s+manana\b/.test(t)) {
    const d = new Date(Date.UTC(anchorDate.getUTCFullYear(), anchorDate.getUTCMonth(), anchorDate.getUTCDate(), 0, 0, 0));
    d.setUTCDate(d.getUTCDate() + 2);
    return d;
  }
  if (/\banteayer\b/.test(t)) {
    const d = new Date(Date.UTC(anchorDate.getUTCFullYear(), anchorDate.getUTCMonth(), anchorDate.getUTCDate(), 0, 0, 0));
    d.setUTCDate(d.getUTCDate() - 2);
    return d;
  }
  if (/\bayer\b/.test(t)) {
    const d = new Date(Date.UTC(anchorDate.getUTCFullYear(), anchorDate.getUTCMonth(), anchorDate.getUTCDate(), 0, 0, 0));
    d.setUTCDate(d.getUTCDate() - 1);
    return d;
  }
  if (/\bmanana\b/.test(t)) {
    const d = new Date(Date.UTC(anchorDate.getUTCFullYear(), anchorDate.getUTCMonth(), anchorDate.getUTCDate(), 0, 0, 0));
    d.setUTCDate(d.getUTCDate() + 1);
    return d;
  }
  if (/\bhoy\b/.test(t)) {
    return new Date(Date.UTC(anchorDate.getUTCFullYear(), anchorDate.getUTCMonth(), anchorDate.getUTCDate(), 0, 0, 0));
  }

  // 3) NUEVO: weekday SOLO ("domingo a las 12:00h...") => próximo weekday
  // Condición de seguridad: debe aparecer el weekday + "a las" o una hora válida cerca
  const mOnly = t.match(/\b(lunes|martes|miercoles|jueves|viernes|sabado|domingo)\b/);
  if (mOnly) {
    const wd = mOnly[1];
    const hasTime = /\ba\s+las\b/.test(t) || extractHourFromText(t) !== "";
    if (hasTime) {
      const targetDow = weekdayMap[wd];
      return nextWeekdayFromAnchor(anchorDate, targetDow, false);
    }
  }

  return null;
}

