const items = $input.all();

return items.map((item) => {
  const original = item.json ?? {};
  const bin = item.binary ? { ...item.binary } : undefined;

  const postParsed = safeJsonParse(original.POST_JSON_RAW);

  const nombreEvento = pickFirstNonEmpty(
    original.NOMBRE_EVENTO,
    original.NOMBRE_DEL_EVENTO,
    original.TITULO,
    original.nombre,
    original.title
  );

  // Anchor (fecha del post) para relativos / año de fechas explícitas
  const postTimeRaw = pickFirstNonEmpty(
    original.FECHA_PUBLICACION, // ej: 30/12/2025
    postParsed?.time,           // ISO
    postParsed?.timestamp,      // seg
    original.time
  );
  const postDate = toDate(postTimeRaw);

  // Texto para heurísticas = texto del post + título (para capturar 30/12/2025 del nombre)
  const baseText = pickFirstNonEmpty(
    original.TEXTO_POST_RAW,
    original.TEXTO_BASE,
    original.TEXTO_POST,
    postParsed?.text,
    original.text
  );
  const textForHeuristics = [baseText, nombreEvento].filter(Boolean).join("\n");

  // 1) Fecha fuerte si existiera
  const strongDateRaw = pickFirstNonEmpty(original.start_time, original.datetime, original.FECHA_RAW, original.TIME_RAW);
  const strongDate = toDate(strongDateRaw);

  // 2) Fecha existente ya calculada
  const existingEventDateRaw = pickFirstNonEmpty(original.FECHA_EVENTO_ISO, original.FECHA_EVENTO, original.DIA_DEL_EVENTO);
  const existingEventDate = toDate(existingEventDateRaw);

  // 3) dd/mm/yyyy en texto/título
  const ddmmyyyy = explicitDDMMYYYY(textForHeuristics);

  // 4) Fecha explícita “30 de diciembre”
  const explicitDate = explicitSpanishDateFromText(textForHeuristics, postDate);

  // 5) Fecha relativa (incluye weekday solo)
  const relDate = relativeDateFromText(textForHeuristics, postDate);

  const eventDate = strongDate || existingEventDate || ddmmyyyy || explicitDate || relDate;

  const eventParts = dateToPartsUTC(eventDate);
  const fechaISO = eventParts ? fmtISODate(eventParts) : "";
  const fechaES  = eventParts ? fmtESDate(eventParts) : "";

  // Hora del evento (solo evidencia)
  const existingHora = pickFirstNonEmpty(original.HORA_EVENTO, original.HORA);
  let horaHM = "";

  if (existingHora) {
    const m = String(existingHora).match(/^\s*([01]?\d|2[0-3])\s*[:hH\.]\s*([0-5]\d)\s*$/);
    horaHM = m ? `${String(m[1]).padStart(2, "0")}:${m[2]}` : String(existingHora).trim();
  } else if (strongDate) {
    const p = dateToPartsUTC(strongDate);
    const hm = p ? fmtHM(p) : "";
    horaHM = hm === "00:00" ? "" : hm;
  } else {
    horaHM = extractHourFromText(textForHeuristics);
  }

  // CODIGO_INTERNO (simple, sin romper tu idempotencia si ya existe)
  const codigoInterno = (original.CODIGO_INTERNO && String(original.CODIGO_INTERNO).trim() !== "")
    ? String(original.CODIGO_INTERNO)
    : [slugClean("facebook"), (fechaISO || "sin_fecha"), (horaHM ? horaHM.replace(":", "") : "sin_hora"), slugClean(nombreEvento || "sin_titulo")].join("_");

  const out = {
    ...original,
    CODIGO_INTERNO: codigoInterno,

    NOMBRE_EVENTO: pickFirstNonEmpty(original.NOMBRE_EVENTO, nombreEvento),

    // Solo si hay evidencia
    FECHA_EVENTO: eventDate ? pickFirstNonEmpty(original.FECHA_EVENTO, fechaES) : (original.FECHA_EVENTO || ""),
    FECHA_EVENTO_ISO: eventDate ? pickFirstNonEmpty(original.FECHA_EVENTO_ISO, fechaISO) : (original.FECHA_EVENTO_ISO || ""),
    DIA_DEL_EVENTO: eventDate ? pickFirstNonEmpty(original.DIA_DEL_EVENTO, fechaISO, fechaES) : (original.DIA_DEL_EVENTO || ""),

    HORA_EVENTO: horaHM ? pickFirstNonEmpty(original.HORA_EVENTO, horaHM) : (original.HORA_EVENTO || ""),
  };

  return bin ? { json: out, binary: bin } : { json: out };
});

// FASE1 — Generar NOMBRE_EVENTO (nunca vacio)
// Reglas:
// - Si ya hay NOMBRE_EVENTO => NO tocar
// - Si está vacío => sacar titulo breve desde TEXTO_BASE (o TEXTO_POST si no hay)
// - Si no se puede => fallback seguro (PUBLICACION ...)
// - NO rellena FECHA_EVENTO / HORA_EVENTO (eso es otra fase)

// Helpers
function normSpaces(s) {
  return String(s ?? '').replace(/\s+/g, ' ').trim();
}

function stripQuotes(s) {
  return String(s ?? '').replace(/^["'“”‘’]+|["'“”‘’]+$/g, '').trim();
}

// Normaliza: MAYUSCULAS, sin acentos, RESPETA Ñ
function normalizeES(str) {
  if (!str) return '';

  const s = String(str);

  // Protege ñ / Ñ
  const protectedÑ = s
    .replace(/ñ/g, '__ENYE_MIN__')
    .replace(/Ñ/g, '__ENYE_MAY__');

  // Quita acentos
  const noAccents = protectedÑ
    .toUpperCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');

  // Restaura Ñ y limpia espacios
  return noAccents
    .replace(/__ENYE_MIN__/g, 'Ñ')
    .replace(/__ENYE_MAY__/g, 'Ñ')
    .replace(/\s+/g, ' ')
    .trim();
}

// Quita "basura" al principio (sin pasarte)
function trimLeadingFillers(s) {
  let out = s.trim();
  const fillers = [
    'HOY', 'ESTA', 'ESTE', 'ESTAS', 'ESTOS',
    'MAÑANA', 'AYER',
    'EL', 'LA', 'LOS', 'LAS',
    'UN', 'UNA', 'UNOS', 'UNAS',
    'EN', 'DE', 'DEL', 'AL',
    'SE', 'NOS', 'OS'
  ];

  // limpia varios tokens iniciales si son fillers
  let guard = 0;
  while (guard < 4) {
    const parts = out.split(' ');
    if (parts.length < 2) break;
    const first = parts[0].replace(/[^\p{L}\p{N}]/gu, '').toUpperCase();
    if (fillers.includes(first)) {
      parts.shift();
      out = parts.join(' ').trim();
      guard++;
      continue;
    }
    break;
  }
  return out;
}

// Crea un titulo tipo "TALLER CARTA A LOS REYES MAGOS" (breve)
function buildTitleFromText(text, maxWords = 10, maxChars = 70) {
  let t = normSpaces(text);
  if (!t) return '';

  // Corta a primera frase "util"
  t = t.split(/\n+/)[0];
  t = t.split(/[.!?]+/)[0];

  t = stripQuotes(t);
  t = trimLeadingFillers(t);

  // recorta a N palabras
  const words = t.split(' ').filter(Boolean);
  const sliced = words.slice(0, maxWords).join(' ');

  // recorta a max chars sin cortar palabra feo
  let out = sliced;
  if (out.length > maxChars) {
    out = out.slice(0, maxChars);
    out = out.replace(/\s+\S*$/g, '').trim(); // quita última palabra incompleta
  }

  // Limpieza final
  out = out.replace(/[-���—]+$/g, '').trim();
  return out;
}

return items.map((item) => {
  const r = item.json || {};

  const ide = normSpaces(r.IDEMPOT_KEY);
  const postId = normSpaces(r.POST_ID);
  const ayto = normSpaces(r.AYTO_ID || r.MUNICIPIO || r.LOCALIDAD);
  const fechaPub = normSpaces(r.FECHA_PUBLICACION);

  // Si ya tiene nombre, lo dejamos tal cual (pero lo normalizamos a mayus/sin acentos)
  const nombreActual = normSpaces(r.NOMBRE_EVENTO);
  if (nombreActual) {
    return {
      json: {
        ...r,
        NOMBRE_EVENTO: normalizeES(nombreActual),
      },
    };
  }

  // Base de texto (tu campo nuevo)
  const base = normSpaces(r.TEXTO_BASE || r.TEXTO_POST || r.TEXTO_POST_RAW);

  let titulo = buildTitleFromText(base, 10, 70);

  // Si aún vacío, fallback seguro
  if (!titulo) {
    if (ayto && fechaPub) titulo = `PUBLICACION ${ayto} - ${fechaPub}`;
    else if (fechaPub) titulo = `PUBLICACION - ${fechaPub}`;
    else if (postId) titulo = `PUBLICACION ${postId}`;
    else if (ide) titulo = `PUBLICACION ${ide}`;
    else titulo = 'PUBLICACION SIN TITULO';
  }

  return {
    json: {
      ...r,
      NOMBRE_EVENTO: normalizeES(titulo),
    },
  };
});

function cleanText(s) {
  if (!s) return '';
  return String(s)
    .replace(/\s+/g, ' ')
    .replace(/[^\p{L}\p{N}\p{P}\p{Zs}]/gu, '') // quita emojis/símbolos raros
    .trim();
}

function cut(s, max = 260) {
  if (!s) return '';
  if (s.length <= max) return s;
  return s.slice(0, max).replace(/\s+\S*$/, '').trim(); // corta sin dejar palabra a medias
}

const out = items.map(item => {
  const r = item.json || {};

  const raw = cleanText(r.TEXTO_POST_RAW);
  const norm = cleanText(r.TEXTO_POST);

  let base = raw || norm;

  // fallback si no hay texto
  if (!base) {
    const muni = (r.MUNICIPIO || r.LOCALIDAD || r.AYTO_ID || '').toString().trim();
    const fpub = (r.FECHA_PUBLICACION || '').toString().trim();
    base = [muni, fpub].filter(Boolean).join(' - ');
    if (!base) base = `PUBLICACION SIN TEXTO (${r.POST_ID || r.IDEMPOT_KEY || 'SIN_ID'})`;
  }

  r.TEXTO_BASE = cut(base, 260);

  return { json: r };
});

return out;

