const items = $input.all();

function norm(v){ return String(v ?? "").trim().toUpperCase(); }
function lower(v){ return String(v ?? "").trim().toLowerCase(); }

function isReel(url){
  const u = lower(url);
  return u.includes("/reel/") || u.includes("facebook.com/reel");
}

function parseNum(v){
  // soporta "0", "5", 0, 5, "", null
  const n = Number(String(v ?? "").trim());
  return Number.isFinite(n) ? n : NaN;
}

const stats = {
  total_in: items.length,
  total_pend: 0,

  // NUM_IMAGENES
  numImgs_0: 0,
  numImgs_gt0: 0,
  numImgs_nan: 0,

  // IMG_URLS
  imgUrls_vacio: 0,
  imgUrls_contenido: 0,

  // TIENE_VIDEO
  tieneVideo_SI: 0,
  tieneVideo_NO: 0,
  tieneVideo_otro: 0,

  // URL reel
  url_reel: 0,
  url_no_reel: 0,

  // Clasificación final (según la regla actual)
  bucket_conImagenes: 0,          // NUM_IMAGENES > 0  OR IMG_URLS no vacío
  bucket_videoSinImagenes: 0,     // sin imágenes + video/reel
  bucket_sinImagenesSinVideo: 0,  // sin imágenes + no video
};

const samples = {
  conImagenes: [],
  videoSinImagenes: [],
  sinImagenesSinVideo: [],
  numImgs_nan: [],
  tieneVideo_otro: [],
};

function pickFields(j){
  return {
    IDEMPOT_KEY: j.IDEMPOT_KEY,
    POST_URL: j.POST_URL,
    NUM_IMAGENES: j.NUM_IMAGENES,
    IMG_URLS: j.IMG_URLS,
    TIENE_VIDEO: j.TIENE_VIDEO,
    FASE2_STATUS: j.FASE2_STATUS,
    TEXTO_POST_LEN: String(j.TEXTO_POST ?? "").length,
    OBS_TAIL: String(j.OBSERVACIONES_DRAMATICOS ?? "").slice(-120),
  };
}

for (const item of items) {
  const j = item.json || {};
  const fase2 = norm(j.FASE2_STATUS);

  if (fase2 !== "PEND_IMG_NO_MATCH") continue;
  stats.total_pend++;

  const nImgs = parseNum(j.NUM_IMAGENES);
  if (Number.isNaN(nImgs)) stats.numImgs_nan++;
  else if (nImgs === 0) stats.numImgs_0++;
  else if (nImgs > 0) stats.numImgs_gt0++;

  const imgUrls = String(j.IMG_URLS ?? "").trim();
  if (imgUrls) stats.imgUrls_contenido++;
  else stats.imgUrls_vacio++;

  const tv = norm(j.TIENE_VIDEO);
  if (tv === "SI") stats.tieneVideo_SI++;
  else if (tv === "NO") stats.tieneVideo_NO++;
  else stats.tieneVideo_otro++;

  const url = String(j.POST_URL ?? "");
  const reel = isReel(url);
  if (reel) stats.url_reel++;
  else stats.url_no_reel++;

  // REGLA "tiene imágenes":
  // (1) NUM_IMAGENES > 0, o (2) IMG_URLS no vacío (por si existe algo)
  const hasImages = (!Number.isNaN(nImgs) && nImgs > 0) || imgUrls.length > 0;

  // REGLA video:
  const isVideo = (tv === "SI") || reel;

  if (hasImages) {
    stats.bucket_conImagenes++;
    if (samples.conImagenes.length < 5) samples.conImagenes.push(pickFields(j));
  } else if (isVideo) {
    stats.bucket_videoSinImagenes++;
    if (samples.videoSinImagenes.length < 5) samples.videoSinImagenes.push(pickFields(j));
  } else {
    stats.bucket_sinImagenesSinVideo++;
    if (samples.sinImagenesSinVideo.length < 5) samples.sinImagenesSinVideo.push(pickFields(j));
  }

  if (Number.isNaN(nImgs) && samples.numImgs_nan.length < 5) {
    samples.numImgs_nan.push(pickFields(j));
  }
  if (tv !== "SI" && tv !== "NO" && samples.tieneVideo_otro.length < 5) {
    samples.tieneVideo_otro.push(pickFields(j));
  }
}

