function stripAccentsKeepEnye(s) {
  return String(s || "")
    .replace(/[ÁÀÄÂ]/g, "A")
    .replace(/[ÉÈËÊ]/g, "E")
    .replace(/[ÍÌÏÎ]/g, "I")
    .replace(/[ÓÒÖÔ]/g, "O")
    .replace(/[ÚÙÜÛ]/g, "U")
    .replace(/[áàäâ]/g, "a")
    .replace(/[éèëê]/g, "e")
    .replace(/[íìïî]/g, "i")
    .replace(/[óòöô]/g, "o")
    .replace(/[úùüû]/g, "u");
}

function norm(s) {
  const t = String(s || "").trim();
  if (!t) return "";
  return stripAccentsKeepEnye(t)
    .toUpperCase()
    .replace(/[\r\n\t]+/g, " ")
    .replace(/\s{2,}/g, " ")
    .trim();
}

function escapeRegExp(str) {
  return String(str || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function containsWordOrPhrase(haystack, needle) {
  if (!needle) return false;
  const n = needle.trim();
  if (!n) return false;

  // si lleva espacios, lo tratamos como frase exacta
  if (/\s/.test(n)) return haystack.includes(n);

  const re = new RegExp(`(^|[^A-Z0-9Ñ])${escapeRegExp(n)}($|[^A-Z0-9Ñ])`, "i");
  return re.test(haystack);
}

function appendObs(oldObs, line) {
  const base = String(oldObs || "").trim();
  const add = String(line || "").trim();
  if (!add) return base;
  if (!base) return add;
  if (base.includes(add)) return base;
  return base + "\n" + add;
}

function isBlank(v) {
  return !String(v ?? "").trim();
}

function toBool(v) {
  if (typeof v === "boolean") return v;
  const s = String(v ?? "").trim().toLowerCase();
  if (!s) return false;
  return ["true", "1", "yes", "si", "sí"].includes(s);
}

const items = $input.all();
const now = new Date().toISOString();

for (const item of items) {
  const j = item.json || {};

  // ------------------------
  // Detectar media / flags
  // ------------------------
  const tieneTexto = String(j.TIENE_TEXTO || "").toUpperCase().trim() === "SI";

  const numImgs = Number(j.NUM_IMAGENES || 0);
  const imgUrls = String(j.IMG_URLS || "").trim();

  // "Hay imagen" si hay IMG_URLS (real) o si el scraper marca fotos
  const hasPhoto = (imgUrls !== "") || numImgs > 0 || toBool(j.MEDIA_HAS_PHOTO);

  const url = String(j.POST_URL || "");
  const postType = String(j.POST_TYPE || "");
  const esReel =
    toBool(j.ES_REEL) ||
    url.includes("/reel/") ||
    url.includes("facebook.com/reel") ||
    /REEL/i.test(postType);

  const tieneVideo =
    toBool(j.TIENE_VIDEO) ||
    toBool(j.MEDIA_HAS_VIDEO) ||
    /VIDEO/i.test(postType) ||
    esReel;

  const fase2Prev = String(j.FASE2_STATUS || "").trim();

  // --------------------------------------------------------------------------
  // REGLA NUEVA (PRIORITARIA):
  // Si hay IMAGENES => LISTO_FASE3_IMG_URLS (tenga texto o no)
  // - EXCEPCION: si NO hay imagenes, seguimos con la logica normal
  // --------------------------------------------------------------------------
  if (hasPhoto) {
    // Si ya estaba LISTO, no re-escribimos
    if (fase2Prev !== "LISTO_FASE3_IMG_URLS") {
      j.FASE2_STATUS = "LISTO_FASE3_IMG_URLS";
      j.FASE2_RUN_AT = now;
      j.FASE2_NOTAS = "AUTO: hasPhoto=true -> LISTO_FASE3_IMG_URLS";
      j.OBSERVACIONES_DRAMATICOS = appendObs(
        j.OBSERVACIONES_DRAMATICOS,
        "FASE2_MEDIA: HAS_PHOTO -> LISTO_FASE3_IMG_URLS"
      );
    }

    // OJO: si hay TEXTO, dejamos que el diccionario siga rellenando ETIQUETAS/TIPO_EVENTO.
    // Si NO hay TEXTO, no hay nada mas que hacer.
    if (!tieneTexto) {
      continue;
    }
    // Si tiene texto, NO hacemos continue: seguimos para clasificar por diccionario,
    // pero manteniendo el status en LISTO_FASE3_IMG_URLS.
  }

  // ------------------------------------------------------------
  // GUARD: si ya está OK_TEXTO, no lo procesamos (idempotente)
  // (pero OJO: arriba ya habremos subido a LISTO si habia fotos)
  // ------------------------------------------------------------
  if (String(j.FASE2_STATUS || "").trim() === "OK_TEXTO") {
    continue;
  }

  // --------------------------------------------------------------------------
  // UPGRADE (se mantiene por compatibilidad):
  // si ya hay IMG_URLS, cualquier PEND_IMG_* pasa a LISTO_FASE3_IMG_URLS
  // --------------------------------------------------------------------------
  if (imgUrls !== "" && /^PEND_IMG_/i.test(fase2Prev)) {
    j.FASE2_STATUS = "LISTO_FASE3_IMG_URLS";
    j.FASE2_RUN_AT = now;
    j.FASE2_NOTAS = `AUTO: upgrade ${fase2Prev} -> LISTO_FASE3_IMG_URLS (IMG_URLS ya presente)`;
    j.OBSERVACIONES_DRAMATICOS = appendObs(
      j.OBSERVACIONES_DRAMATICOS,
      `FASE2_UPGRADE: ${fase2Prev} -> LISTO_FASE3_IMG_URLS`
    );
    continue;
  }

  // ------------------------------------------------------------
  // CASO 0: SIN TEXTO -> ruteo solo por media
  // (si hasPhoto=true, ya lo hemos marcado arriba como LISTO y continuado)
  // ------------------------------------------------------------
  if (!tieneTexto) {
    if (isBlank(j.FASE2_STATUS)) {
      if (!hasPhoto && tieneVideo) {
        j.FASE2_STATUS = "FASE10_VIDEOSINPROCESAR";
        j.FASE2_RUN_AT = now;
        j.FASE2_NOTAS = "AUTO: sin texto y sin imagenes -> video/reel (FASE10)";
        j.OBSERVACIONES_DRAMATICOS = appendObs(
          j.OBSERVACIONES_DRAMATICOS,
          "FASE10: VIDEO/REEL SIN TEXTO (SIN IMAGENES)"
        );
      } else if (hasPhoto) {
        // (en teoria no entra aquí por el bloque prioritario, pero lo dejamos por seguridad)
        j.FASE2_STATUS = "LISTO_FASE3_IMG_URLS";
        j.FASE2_RUN_AT = now;
        j.FASE2_NOTAS = "AUTO: sin texto pero con fotos -> LISTO_FASE3_IMG_URLS";
        j.OBSERVACIONES_DRAMATICOS = appendObs(
          j.OBSERVACIONES_DRAMATICOS,
          "FASE2_MEDIA: SIN TEXTO CON FOTOS -> LISTO_FASE3_IMG_URLS"
        );
      } else {
        j.FASE2_STATUS = "DESCARTADO_SIN_CONTENIDO";
        j.FASE2_RUN_AT = now;
        j.FASE2_NOTAS = "AUTO: sin texto, sin fotos, sin video -> descartado";
        j.OBSERVACIONES_DRAMATICOS = appendObs(
          j.OBSERVACIONES_DRAMATICOS,
          "DESCARTADO: SIN CONTENIDO UTIL"
        );
      }
    }
    continue;
  }

  // ------------------------------------------------------------
  // CASO 1+: CON TEXTO -> diccionario
  // ------------------------------------------------------------
  const dic = Array.isArray(j.__DIC_ETIQUETAS) ? j.__DIC_ETIQUETAS : [];
  const nombre = norm(j.NOMBRE_EVENTO);
  const texto = norm(j.TEXTO_POST);

  const matches = [];

  for (const row of dic) {
    const etiqueta = norm(row.ETIQUETA || row.Etiqueta || row.etiqueta);
    const tipo = norm(row.TIPO_EVENTO || row.Tipo_Evento || row.tipo_evento);
    const prioRaw = row.PRIORIDAD ?? row.Prioridad ?? row.prioridad;
    const prioridad = Number(prioRaw);

    if (!etiqueta || !Number.isFinite(prioridad)) continue;

    const sinRaw = String(row.SINONIMOS || row.Sinonimos || row.sinonimos || "").trim();
    if (!sinRaw) continue;

    const synonyms = sinRaw.split(";").map(s => norm(s)).filter(Boolean);
    if (!synonyms.length) continue;

    let foundIn = "";
    let foundToken = "";

    // 1) Buscar en NOMBRE
    for (const syn of synonyms) {
      if (nombre && containsWordOrPhrase(nombre, syn)) {
        foundIn = "NOMBRE";
        foundToken = syn;
        break;
      }
    }

    // 2) Buscar en TEXTO
    if (!foundIn) {
      for (const syn of synonyms) {
        if (texto && containsWordOrPhrase(texto, syn)) {
          foundIn = "TEXTO";
          foundToken = syn;
          break;
        }
      }
    }

    if (foundIn) {
      matches.push({
        ETIQUETA: etiqueta,
        TIPO_EVENTO: tipo,
        PRIORIDAD: prioridad,
        FOUND_IN: foundIn,
        TOKEN: foundToken,
        TOKEN_LEN: foundToken.length,
      });
    }
  }

  // Orden: prioridad asc (más importante), luego token más largo
  matches.sort((a, b) => {
    if (a.PRIORIDAD !== b.PRIORIDAD) return a.PRIORIDAD - b.PRIORIDAD;
    return (b.TOKEN_LEN || 0) - (a.TOKEN_LEN || 0);
  });

  const best = matches[0] || null;

  if (!best) {
    // NO MATCH
    if (isBlank(j.FASE2_STATUS)) {
      if (!hasPhoto && tieneVideo) {
        j.FASE2_STATUS = "FASE10_VIDEOSINPROCESAR";
        j.FASE2_RUN_AT = now;
        j.FASE2_NOTAS = "AUTO: con texto pero sin match y sin imagenes -> video/reel (FASE10)";
        j.OBSERVACIONES_DRAMATICOS = appendObs(
          j.OBSERVACIONES_DRAMATICOS,
          "FASE10: VIDEO/REEL (NO MATCH, SIN IMAGENES)"
        );
      } else {
        // Si hasPhoto=true, ya vendria marcado como LISTO arriba.
        // Si no hay foto, caemos al descarte de siempre.
        j.FASE2_STATUS = "DESCARTADO_SIN_IMAGENES";
        j.FASE2_RUN_AT = now;
        j.FASE2_NOTAS = "AUTO: no match, sin fotos, sin video -> descartado";
        j.OBSERVACIONES_DRAMATICOS = appendObs(
          j.OBSERVACIONES_DRAMATICOS,
          "DESCARTADO: NO MATCH SIN MEDIA"
        );
      }
    }
  } else {
    const samePrio = matches.filter(m => m.PRIORIDAD === best.PRIORIDAD);
    const uniqueEtiquetas = [...new Set(samePrio.map(m => m.ETIQUETA))];

    if (uniqueEtiquetas.length > 1) {
      // AMBIGUO
      if (isBlank(j.FASE2_STATUS)) {
        if (!hasPhoto && tieneVideo) {
          j.FASE2_STATUS = "FASE10_VIDEOSINPROCESAR";
          j.FASE2_RUN_AT = now;
          j.FASE2_NOTAS = "AUTO: ambiguo y sin imagenes -> video/reel (FASE10)";
          j.OBSERVACIONES_DRAMATICOS = appendObs(
            j.OBSERVACIONES_DRAMATICOS,
            "FASE10: AMBIGUO VIDEO/REEL (SIN IMAGENES)"
          );
        } else {
          // Si hasPhoto=true, ya vendria LISTO arriba.
          j.FASE2_STATUS = "DESCARTADO_AMBIGUO";
          j.FASE2_RUN_AT = now;
          j.FASE2_NOTAS = "AUTO: ambiguo sin media -> descartado";
          j.OBSERVACIONES_DRAMATICOS = appendObs(
            j.OBSERVACIONES_DRAMATICOS,
            "DESCARTADO: AMBIGUO SIN MEDIA"
          );
        }
      }
    } else {
      // RESUELTO
      j.ETIQUETAS = best.ETIQUETA;
      j.TIPO_EVENTO = best.TIPO_EVENTO || "";

      j.OBSERVACIONES_DRAMATICOS = appendObs(
        j.OBSERVACIONES_DRAMATICOS,
        `FASE2_OK(${best.FOUND_IN}): ${best.ETIQUETA} -> ${best.TIPO_EVENTO} [${best.TOKEN}]`
      );

      if (isBlank(j.FASE2_STATUS)) {
        // si no hay imagen, el status normal es OK_TEXTO
        j.FASE2_STATUS = "OK_TEXTO";
        j.FASE2_RUN_AT = now;
        j.FASE2_NOTAS = `AUTO: resuelto por ${best.FOUND_IN} [${best.TOKEN}]`;
      }
      // si hasPhoto=true, el status ya es LISTO_FASE3_IMG_URLS por el bloque prioritario
    }
  }

  // ------------------------------------------------------------
  // Paracaídas anti-blancos
  // ------------------------------------------------------------
  if (isBlank(j.FASE2_STATUS)) {
    j.FASE2_STATUS = "FASE2_SIN_CLASIFICAR";
    j.FASE2_RUN_AT = now;
    j.FASE2_NOTAS = "AUTO: fallback";
    j.OBSERVACIONES_DRAMATICOS = appendObs(j.OBSERVACIONES_DRAMATICOS, "FASE2: FALLBACK");
  }
}

return items;

// ═══════════════════════════════════════════════════════════
// BUILD FB_POST_MEDIA ROWS (BATCH)
// Entrada: items = POSTS (desde Filter o directamente desde Sheets)
// Salida: items = filas individuales para Sheets (FB_POST_MEDIA)
// - sin crypto
// - filename real FB desde la URL (sin query)
// - rellena ROOT/AYTO/YEAR/MONTH/POST aunque no vengan en el input
// - nunca devuelve undefined (usa '' o 0)
// ═══════════════════════════════════════════════════════════

const ROOT_CONST = '/0-CANCERBERO/EVENTOS_FB';
const posts = $input.all().map(i => i.json);

const nowSpain = new Date()
  .toLocaleString("sv-SE", { timeZone: "Europe/Madrid" })
  .replace('T',' ');

const meses = [
  '',
  '01 - ENERO','02 - FEBRERO','03 - MARZO','04 - ABRIL','05 - MAYO','06 - JUNIO',
  '07 - JULIO','08 - AGOSTO','09 - SEPTIEMBRE','10 - OCTUBRE','11 - NOVIEMBRE','12 - DICIEMBRE'
];

const norm = (v) =>
  (v ?? '')
    .toString()
    .replace(/\u00A0/g, ' ')
    .trim();

function safeStr(v) {
  return (v === undefined || v === null) ? '' : String(v);
}

function randId6() {
  return Math.random().toString(36).slice(2, 8);
}

// "hash" simple determinista (sin crypto) a 12 chars: basename limpio recortado
function hash12FromBasename(base) {
  const clean = safeStr(base)
    .replace(/\.[a-z0-9]+$/i, '')
    .replace(/[^a-zA-Z0-9_]+/g, '');
  return (clean || 'MEDIA').slice(0, 12).padEnd(12, '0');
}

function getFbFilenameAndNorm(url) {
  try {
    const u = new URL(url);
    const pathParts = u.pathname.split('/').filter(Boolean);
    const fbFile = pathParts[pathParts.length - 1] || '';
    const ext = (fbFile.split('.').pop() || '').toLowerCase();
    const urlNorm = `${u.origin}${u.pathname}`; // sin query
    return { fbFile, ext, urlNorm };
  } catch (e) {
    const noQuery = safeStr(url).split('?')[0];
    const parts = noQuery.split('/').filter(Boolean);
    const fbFile = parts[parts.length - 1] || 'media.jpg';
    const ext = (fbFile.split('.').pop() || 'jpg').toLowerCase();
    return { fbFile, ext, urlNorm: noQuery };
  }
}

// MIME correcto (evita image/jpg -> image/jpeg)
function mimeFromExt(ext, mediaType) {
  const e = safeStr(ext).toLowerCase();
  const mt = safeStr(mediaType).toUpperCase();

  if (mt === 'VIDEO') {
    if (e === 'mp4') return 'video/mp4';
    if (e === 'mov') return 'video/quicktime';
    if (e === 'webm') return 'video/webm';
    return `video/${e || 'mp4'}`;
  }

  if (e === 'jpg' || e === 'jpeg') return 'image/jpeg';
  if (e === 'png') return 'image/png';
  if (e === 'webp') return 'image/webp';
  if (e === 'gif') return 'image/gif';
  return `image/${e || 'jpeg'}`;
}

// Split robusto: mantiene tu formato principal " | " pero tolera otros
function splitUrls(raw) {
  const s = safeStr(raw).trim();
  if (!s) return [];
  return s
    .split(' | ')
    .flatMap(part => part.split('\n'))
    .flatMap(part => part.split(','))
    .map(u => u.trim())
    .filter(Boolean);
}

// Fallback de carpeta: replica la lógica del Filter antiguo
function computeFolderContext(post) {
  // ROOT
  const ROOT = safeStr(post.__ROOT || post.ROOT) || ROOT_CONST;

  // AYTO (nombre de carpeta)
  const aytoId = norm(post.AYTO_ID || post.AYTO);
  const AYTO = safeStr(post.__AYTO || post.AYTO) || ('AYTO. ' + aytoId.replace(/_/g, ' '));

  // YEAR + MONTH (desde FECHA_PUBLICACION si existe)
  const fechaPub = norm(post.FECHA_PUBLICACION);
  let YEAR = safeStr(post.__YEAR || post.YEAR);
  let MONTH = safeStr(post.__MONTH || post.MONTH);

  if ((!YEAR || !MONTH) && fechaPub) {
    const parts = fechaPub.split('/');
    const m = parseInt(parts[1], 10);
    const y = parts[2];
    if (!YEAR) YEAR = y || '';
    if (!MONTH) MONTH = meses[m] || '';
  }

  // POST (slug)
  const IDEMPOT_KEY = norm(post.IDEMPOT_KEY);
  const POST = safeStr(post.__POST || post.POST) || IDEMPOT_KEY.replace(/\s+/g, '_');

  return { ROOT, AYTO, YEAR, MONTH, POST };
}

const out = [];

for (const post of posts) {
  const IDEMPOT_KEY = norm(post.IDEMPOT_KEY);
  const AYTO_ID = norm(post.AYTO_ID || post.AYTO);

  const { ROOT, AYTO, YEAR, MONTH, POST } = computeFolderContext(post);

  const rawUrls = post.IMG_URLS || post.MEDIA_URLS || '';
  const urls = splitUrls(rawUrls);

  const mediaType = norm(post.MEDIA_TYPE || 'IMAGE').toUpperCase() || 'IMAGE';

  // Si un post viene sin IMG_URLS, NO rompemos el batch: 1 fila ERROR (con carpetas ya rellenas)
  if (urls.length === 0) {
    out.push({
      json: {
        MEDIA_ID: randId6(),
        IDEMPOT_KEY,
        AYTO_ID,

        MEDIA_TYPE: mediaType,
        MEDIA_URL: '',
        MEDIA_URL_NORM: '',

        MEDIA_HASH12: '',
        FILE_EXT: '',
        FILE_BASENAME: '',
        FILE_NAME: '',
        MIME_TYPE: '',

        MEDIA_INDEX: 0,
        MEDIA_TOTAL: 0,

        STATUS: 'ERROR',
        RUN_COUNT: 0,
        ERROR_MSG: 'NO_IMG_URLS_MEDIA_URLS',

        CREATED_AT: nowSpain,
        UPDATED_AT: nowSpain,

        ROOT,
        AYTO,
        YEAR,
        MONTH,
        POST,

        DRIVE_FOLDER_POST_ID: '',
        DRIVE_FILE_ID: '',
        DRIVE_FILE_URL: '',
        FILE_SIZE_BYTES: '',
      }
    });
    continue;
  }

  for (let i = 0; i < urls.length; i++) {
    const mediaUrl = urls[i];
    const { fbFile, ext, urlNorm } = getFbFilenameAndNorm(mediaUrl);

    const fileName = fbFile || `img_${i + 1}.jpg`;
    const fileExt = ext || 'jpg';
    const fileBase = fileName.replace(new RegExp(`\\.${fileExt}$`, 'i'), '');

    out.push({
      json: {
        MEDIA_ID: randId6(),
        IDEMPOT_KEY,
        AYTO_ID,

        MEDIA_TYPE: mediaType,
        MEDIA_URL: safeStr(mediaUrl),
        MEDIA_URL_NORM: safeStr(urlNorm),

        MEDIA_HASH12: hash12FromBasename(fileBase),
        FILE_EXT: safeStr(fileExt),
        FILE_BASENAME: safeStr(fileBase),
        FILE_NAME: safeStr(fileName),
        MIME_TYPE: mimeFromExt(fileExt, mediaType),

        MEDIA_INDEX: i + 1,
        MEDIA_TOTAL: urls.length,

        STATUS: 'PENDIENTE_DESCARGA',
        RUN_COUNT: 0,
        ERROR_MSG: '',

        CREATED_AT: nowSpain,
        UPDATED_AT: nowSpain,

        ROOT,
        AYTO,
        YEAR,
        MONTH,
        POST,

        DRIVE_FOLDER_POST_ID: '',
        DRIVE_FILE_ID: '',
        DRIVE_FILE_URL: '',
        FILE_SIZE_BYTES: '',
      }
    });
  }
}

console.log(`FB_POST_MEDIA: posts=${posts.length} -> media rows=${out.length}`);
return out;

// Preparar datos para descarga
const row = $input.first().json;

const MEDIA_ID = String(row.MEDIA_ID || '').trim();
const MEDIA_URL = String(row.MEDIA_URL || '').trim();
const ROOT = String(row.ROOT || '/FB_MEDIA').trim();
const AYTO = String(row.AYTO || '').trim();
const YEAR = String(row.YEAR || '').trim();
const MONTH = String(row.MONTH || '').trim();
const POST = String(row.POST || '').trim();
const FILE_NAME = String(row.FILE_NAME || MEDIA_ID || `img_${Date.now()}.jpg`).trim();

// Construir path de Dropbox - las carpetas se crean automáticamente
const dropboxPath = `${ROOT}/${AYTO}/${YEAR}/${MONTH}/${POST}/${FILE_NAME}`;

console.log(`DOWNLOAD: ${MEDIA_ID} -> ${dropboxPath}`);

return [{
  json: {
    MEDIA_ID: MEDIA_ID,
    MEDIA_URL: MEDIA_URL,
    DROPBOX_PATH: dropboxPath,
    FILE_NAME: FILE_NAME
  }
}];

// Combinar contexto + binary
const item = $input.first();
const ctx = $('3. Prep').first().json;

return [{
  json: ctx,
  binary: item.binary
}];

const upload = $input.first().json;
const ctx = $('5. Merge').first().json;

console.log(`✅ UPLOADED: ${ctx.MEDIA_ID} -> ${ctx.DROPBOX_PATH}`);

return [{ json: { done: true } }];

// ===============================================
// PARSE DUAL OCR + PREANALYSIS + GRUPO_ID_OCR
// ===============================================

const ocrResponse = $input.first().json;
const ctx = $('5. To Base').first().json;

// ---------- helpers ----------
function cheapHash(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) {
    h = (h << 5) - h + str.charCodeAt(i);
    h |= 0;
  }
  return Math.abs(h).toString(36);
}

function norm(str) {
  return String(str || '')
    .toUpperCase()
    .replace(/[ÁÀÄ]/g, 'A')
    .replace(/[ÉÈË]/g, 'E')
    .replace(/[ÍÌÏ]/g, 'I')
    .replace(/[ÓÒÖ]/g, 'O')
    .replace(/[ÚÙÜ]/g, 'U')
    .replace(/[^A-Z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

// ---------- Extraer campos DUAL OCR ----------
const OCR_PADDLE_RAW = ocrResponse.OCR_PADDLE_RAW || '';
const OCR_PADDLE_LEN = ocrResponse.OCR_PADDLE_LEN || 0;
const OCR_PADDLE_SCORE = ocrResponse.OCR_PADDLE_SCORE || 0;

const OCR_TESSERACT_RAW = ocrResponse.OCR_TESSERACT_RAW || '';
const OCR_TESSERACT_LEN = ocrResponse.OCR_TESSERACT_LEN || 0;
const OCR_TESSERACT_SCORE = ocrResponse.OCR_TESSERACT_SCORE || 0;

const OCR_WINNER = ocrResponse.OCR_WINNER || 'NONE';
const OCR_WIN_TEXT = ocrResponse.OCR_WIN_TEXT || '';
const OCR_WIN_SCORE = ocrResponse.OCR_WIN_SCORE || 0;
const OCR_LEVEL = ocrResponse.OCR_LEVEL || 'DESCARTADO_BASURA';
const NEEDS_GVISION = ocrResponse.NEEDS_GVISION || false;

const paddle_success = ocrResponse.paddle_success || false;
const tesseract_success = ocrResponse.tesseract_success || false;

// ---------- Usar texto ganador para PREANALYSIS ----------
const textRaw = OCR_WIN_TEXT;
const textLen = textRaw.length;
const isOcrEmpty = textLen === 0;

// ---------- PREANALYSIS: señales de cartel ----------
let cartelScore = 0;
let POST_CARTEL_OK = false;

if (!isOcrEmpty) {
  const hasWeekday = /(LUNES|MARTES|MIERCOLES|JUEVES|VIERNES|SABADO|DOMINGO)/i.test(textRaw);
  const hasDate = /\b\d{1,2}\s*(DE)?\s*(ENERO|FEBRERO|MARZO|ABRIL|MAYO|JUNIO|JULIO|AGOSTO|SEPTIEMBRE|OCTUBRE|NOVIEMBRE|DICIEMBRE)\b/i.test(textRaw);
  const hasHour = /\b\d{1,2}[:.]\d{2}\b|\b\d{1,2}\s*H\b/i.test(textRaw);
  const hasPlace = /(CENTRO|SALON|BIBLIOTECA|PLAZA|AUDITORIO|TEATRO|CENTRO DE DIA)/i.test(textRaw);

  // Scoring
  if (textLen >= 120) cartelScore += 40;
  if (hasWeekday || hasDate) cartelScore += 20;
  if (hasHour) cartelScore += 15;
  if (hasPlace) cartelScore += 15;

  // Bonus por OCR_WIN_SCORE alto
  if (OCR_WIN_SCORE >= 70) cartelScore += 10;

  POST_CARTEL_OK = cartelScore >= 70;
}

// ---------- GRUPO_ID_OCR ----------
let signature = '';
if (POST_CARTEL_OK && textRaw) {
  signature = norm(textRaw).split(' ').slice(0, 40).join(' ');
}
if (!signature) {
  signature = norm(ctx.FILE_BASENAME || ctx.MEDIA_ID || '');
}

let GRUPO_ID_OCR = '';
if (signature) {
  const base = [ctx.AYTO_ID || '', ctx.YEAR || '', signature].join('|');
  GRUPO_ID_OCR = 'G_' + cheapHash(base).slice(0, 12);
}

// ---------- Determinar PROCESS_STAGE ----------
let PROCESS_STAGE;
if (isOcrEmpty) {
  PROCESS_STAGE = 'OCR_EMPTY';
} else if (OCR_LEVEL === 'DESCARTADO_BASURA') {
  PROCESS_STAGE = 'OCR_DESCARTADO';
} else if (NEEDS_GVISION) {
  PROCESS_STAGE = 'PENDIENTE_GVISION';
} else {
