// Agrupar por GRUPO_ID_OCR y decidir qué pasa a Vision

const items = $input.all().map(i => i.json);

function ts(row) {
  return new Date(row.UPDATED_AT || row.CREATED_AT || row.OCR_AT || 0).getTime();
}

const groups = {};
for (const r of items) {
  const g = r.GRUPO_ID_OCR || 'NO_GROUP';
  if (!groups[g]) groups[g] = [];
  groups[g].push(r);
}

const out = [];

for (const g of Object.keys(groups)) {
  const arr = groups[g].sort((a, b) => ts(b) - ts(a)); // más nuevo primero

  arr.forEach((r, idx) => {
    const isUltimo = idx === 0;
    const score = Number(r.CARTEL_SCORE || 0);
    const needsGvision = r.NEEDS_GVISION === true || r.NEEDS_GVISION === 'true' || r.NEEDS_GVISION === 'TRUE';

    let pick = false;
    let reason = 'DESCARTADO';

    // Lógica de decisión
    if (needsGvision) {
      // Si NEEDS_GVISION=true (score 20-40), siempre va a Vision
      pick = true;
      reason = 'NEEDS_GVISION';
    } else if (isUltimo) {
      // El más reciente del grupo va a Vision
      pick = true;
      reason = 'ULTIMO_GRUPO';
    } else if (score >= 80) {
      // Carteles con score muy alto también van
      pick = true;
      reason = 'CARTEL_SCORE_ALTO';
    } else {
      reason = 'DESCARTADO_POR_SCORE_O_ANTIGUO';
