    out.push({
      MEDIA_ID: r.MEDIA_ID,
      GRUPO_ID_OCR: g,
      POST_ORDEN_INV: idx + 1,
      POST_ES_ULTIMO: isUltimo ? 'TRUE' : 'FALSE',
      POST_PICK_VISION: pick ? 'TRUE' : 'FALSE',
      POST_PICK_REASON: reason,
      PROCESS_STAGE: pick ? 'PENDIENTE_VISION' : 'PREANALYSIS_DONE'
    });
  });
}

