// ============================================================================
// EXTRACT EVENT FIELDS (SIN INVENTAR)
// Reglas:
// - FECHA_EXTR: DD/MM/YYYY. Si no hay dia+mes en OCR => blanco. Año SIEMPRE desde YEAR (Sheet).
// - HORA_EXTR: HH:MM solo si aparece con ":" (ej 12:00). Si no => blanco.
// - MUNICIPIO_EXTR: por defecto AYTO_ID. Solo cambia si OCR detecta otro municipio distinto.
// - LOCALIDAD_EXTR: igual que municipio salvo detección clara de otra localidad.
// - LOCAL_EXTR: buscar línea con SALON/CENTRO/TEATRO/etc.
// - PRECIO_EXTR: si no se detecta => blanco.
// - TITULO_EXTR: primeras líneas útiles sin meter municipio.
// ============================================================================

function safeStr(v) { return (v === null || v === undefined) ? '' : String(v); }
function pad2(n) { const x = String(n); return x.length === 1 ? '0' + x : x; }

function normalizeEsKeepEnye(str) {
  if (!str) return '';
  let s = String(str);
  s = s.replace(/ñ/g, '%%ENYE%%').replace(/Ñ/g, '%%ENYE_UP%%');
  s = s.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  s = s.replace(/%%ENYE%%/g, 'Ñ').replace(/%%ENYE_UP%%/g, 'Ñ');
  return s.toUpperCase().trim();
}

function monthFromName(mes) {
  const map = {
    ENERO: 1, FEBRERO: 2, MARZO: 3, ABRIL: 4, MAYO: 5, JUNIO: 6,
    JULIO: 7, AGOSTO: 8, SEPTIEMBRE: 9, SETIEMBRE: 9, OCTUBRE: 10, NOVIEMBRE: 11, DICIEMBRE: 12
  };
  return map[mes] || null;
}

function findLocalLine(linesNorm, linesRaw) {
  const reLocal = /\b(SALON|SALÓN|CENTRO|TEATRO|AUDITORIO|CASA|PLAZA|PABELLON|PABELLÓN|RECINTO|PARQUE|PASEO|AVENIDA|CALLE)\b/i;
  for (let i = 0; i < linesNorm.length; i++) {
    if (reLocal.test(linesNorm[i])) return { value: linesNorm[i], evidence: linesRaw[i] };
  }
  return null;
}

function detectPlaceFromOCR(linesNorm, linesRaw) {
  for (let i = 0; i < linesNorm.length - 1; i++) {
    const a = linesNorm[i];
    const b = linesNorm[i + 1];
    if (!a || !b) continue;
    if (/\d/.test(a) || /\d/.test(b)) continue;
    if (/^DE\s+/.test(b)) {
      const cand = `${a} ${b}`.replace(/\s+/g, ' ').trim();
      const words = cand.split(/\s+/).filter(Boolean);
      if (words.length >= 3 && words.length <= 8) {
        return { value: cand, evidence: `${linesRaw[i]} | ${linesRaw[i + 1]}` };
      }
    }
  }
  for (let i = 0; i < linesNorm.length; i++) {
    const ln = linesNorm[i];
    if (!ln) continue;
    if (/\d/.test(ln)) continue;
    if (/\bDE\b/.test(ln)) {
      const words = ln.split(/\s+/).filter(Boolean);
      if (words.length >= 3 && words.length <= 8) {
        return { value: ln, evidence: linesRaw[i] };
      }
    }
  }
  return null;
}

function extractBestHour(linesRaw) {
  const all = [];
  for (const line of linesRaw) {
    const matches = line.match(/\b([01]?\d|2[0-3]):([0-5]\d)\b/g);
    if (matches) for (const t of matches) all.push({ t, line });
  }
  if (!all.length) return { value: '', evidence: '' };
  const withHoras = all.find(x => normalizeEsKeepEnye(x.line).includes('HORAS'));
  const chosen = withHoras || all[all.length - 1];
  const [h, m] = chosen.t.split(':');
  return { value: `${pad2(parseInt(h,10))}:${pad2(parseInt(m,10))}`, evidence: chosen.line };
}

function extractDateDMY(textNorm, linesRaw, yearBase) {
  if (!yearBase) return { value: '', evidence: '' };

  const mNum = textNorm.match(/\b(\d{1,2})[\/\-\.](\d{1,2})[\/\-\.](\d{2,4})\b/);
  if (mNum) {
    const dd = parseInt(mNum[1], 10);
    const mm = parseInt(mNum[2], 10);
    let yy = parseInt(mNum[3], 10);
    if (yy < 100) yy += 2000;
    const val = `${pad2(dd)}/${pad2(mm)}/${yy}`;
    const ev = linesRaw.find(l => normalizeEsKeepEnye(l).includes(mNum[0])) || mNum[0];
    return { value: val, evidence: ev };
  }

  const mTxt = textNorm.match(/\b(?:LUNES|MARTES|MIERCOLES|MIÉRCOLES|JUEVES|VIERNES|SABADO|SÁBADO|DOMINGO)?\s*(\d{1,2})\s+(ENERO|FEBRERO|MARZO|ABRIL|MAYO|JUNIO|JULIO|AGOSTO|SEPTIEMBRE|SETIEMBRE|OCTUBRE|NOVIEMBRE|DICIEMBRE)\b/);
  if (mTxt) {
    const dd = parseInt(mTxt[1], 10);
    const mm = monthFromName(mTxt[2]);
    if (!mm) return { value: '', evidence: '' };
    const val = `${pad2(dd)}/${pad2(mm)}/${yearBase}`;
    const ev = linesRaw.find(l => normalizeEsKeepEnye(l).includes(String(dd)) && normalizeEsKeepEnye(l).includes(mTxt[2])) || mTxt[0];
    return { value: val, evidence: ev };
  }

  return { value: '', evidence: '' };
}

function extractTitle(linesNorm, linesRaw, aytoNorm) {
  const parts = [];
  const evid = [];
  for (let i = 0; i < Math.min(linesNorm.length, 6); i++) {
    const ln = linesNorm[i];
    const raw = linesRaw[i];
    if (!ln) continue;
    if (/\b([01]?\d|2[0-3]):[0-5]\d\b/.test(ln)) continue;
    if (/\b(LUNES|MARTES|MIERCOLES|MIÉRCOLES|JUEVES|VIERNES|SABADO|SÁBADO|DOMINGO)\b/.test(ln)) continue;
    if (/\b(ENERO|FEBRERO|MARZO|ABRIL|MAYO|JUNIO|JULIO|AGOSTO|SEPTIEMBRE|SETIEMBRE|OCTUBRE|NOVIEMBRE|DICIEMBRE)\b/.test(ln)) continue;
    if (/\b(INFANTIL|HORAS?|OS\s+ESPERAMOS)\b/.test(ln)) continue;
    if (aytoNorm && (ln === aytoNorm || ln.includes(aytoNorm))) continue;
    if (ln.length < 4) continue;
    parts.push(ln);
    evid.push(raw);
    if (parts.length >= 2) break;
  }
  return { value: parts.join(' ').replace(/\s+/g,' ').trim(), evidence: evid.join(' | ').trim() };
}

const items = $input.all();
const results = [];

for (const item of items) {
  const j = item.json || {};

  const YEAR_BASE = parseInt(safeStr(j.YEAR), 10);
  const AYTO_ID = normalizeEsKeepEnye(j.AYTO_ID || j.AYTO || '');

  // Usar OCR_GVISION_RAW preferentemente, fallback a OCR_TEXT_RAW
  const ocr = safeStr(j.OCR_GVISION_RAW || j.OCR_TEXT_RAW || j.OCR_WIN_TEXT || '');
  const linesRaw = ocr.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
  const linesNorm = linesRaw.map(normalizeEsKeepEnye);
  const textNorm = normalizeEsKeepEnye(ocr);

  const hora = extractBestHour(linesRaw);
  const fecha = extractDateDMY(textNorm, linesRaw, (!isNaN(YEAR_BASE) ? YEAR_BASE : null));
  const placeOCR = detectPlaceFromOCR(linesNorm, linesRaw);
  const placeVal = placeOCR ? placeOCR.value : AYTO_ID;
  const local = findLocalLine(linesNorm, linesRaw);
  const title = extractTitle(linesNorm, linesRaw, AYTO_ID);

  let PRECIO_EXTR = '';
  let EVID_PRECIO = '';
  const mPrecioEur = ocr.match(/\b\d{1,3}([.,]\d{2})?\s?€\b/);
  if (mPrecioEur) {
    PRECIO_EXTR = mPrecioEur[0];
    EVID_PRECIO = linesRaw.find(l => l.includes(mPrecioEur[0])) || mPrecioEur[0];
  } else {
    const mGratis = textNorm.match(/\b(GRATIS|GRATUITO|ENTRADA\s+LIBRE)\b/);
    if (mGratis) {
      PRECIO_EXTR = mGratis[0];
      EVID_PRECIO = linesRaw.find(l => normalizeEsKeepEnye(l).includes(mGratis[0])) || mGratis[0];
    }
  }

  let score = 0;
  if (title.value) score += 10;
  if (fecha.value) score += 35;
  if (hora.value) score += 25;
  if (placeVal) score += 15;
  if (local) score += 15;
  if (PRECIO_EXTR) score += 10;
  if (score > 100) score = 100;

  const evidenciaObj = {
    TITULO: title.evidence,
    FECHA: fecha.evidence,
    HORA: hora.evidence,
    MUNICIPIO: placeOCR ? placeOCR.evidence : (AYTO_ID ? 'AYTO_ID' : ''),
    LOCAL: local ? local.evidence : '',
    PRECIO: EVID_PRECIO,
    YEAR_BASE: (!isNaN(YEAR_BASE) ? String(YEAR_BASE) : ''),
    AYTO_ID: AYTO_ID
  };

  const extractObj = {
    TITULO_EXTR: title.value,
    FECHA_EXTR: fecha.value,
    HORA_EXTR: hora.value,
    LOCAL_EXTR: local ? local.value : '',
    LOCALIDAD_EXTR: placeVal || AYTO_ID || '',
    MUNICIPIO_EXTR: placeVal || AYTO_ID || '',
    PRECIO_EXTR: PRECIO_EXTR,
    CONFIANZA_EXTR: String(score),
    EVIDENCIA_EXTR: evidenciaObj
  };

  results.push({
    json: {
      ...j,
      EXTRACT_JSON: JSON.stringify(extractObj),
      TITULO_EXTR: title.value,
      FECHA_EXTR: fecha.value,
      HORA_EXTR: hora.value,
      LOCAL_EXTR: local ? local.value : '',
      LOCALIDAD_EXTR: placeVal || AYTO_ID || '',
      MUNICIPIO_EXTR: placeVal || AYTO_ID || '',
      PRECIO_EXTR: PRECIO_EXTR,
      CONFIANZA_EXTR: String(score),
      EVIDENCIA_EXTR: JSON.stringify(evidenciaObj)
    }
  });
}

return results;

// ============================================================================
// OCR WINNER + CANDIDATOS_RESULT
// Reglas:
// - EN_PROCESO: STATUS o PROCESS_STAGE ∈ {UPLOADED_TO_DROPBOX, PENDIENTE_DESCARGA}
// - DESCARTADO: STATUS=OCR_EMPTY OR (STATUS=OCR_ERROR && OCR_TEXT_LEN<20)
// - DUDOSO: si FECHA_EXTR vacío
// - SELECCIONADO: si hay FECHA_EXTR y OCR_WINNER != NONE y texto ganador >= 80
// ============================================================================

const IN_PROCESS = new Set(['UPLOADED_TO_DROPBOX', 'PENDIENTE_DESCARGA']);

function str(v) {
  return (v ?? '').toString();
}
function normText(t) {
  return str(t).replace(/\r/g, '').trim();
}

function flagsFromText(t, aytoId) {
  const s = normText(t);
  const ayto = normText(aytoId).toUpperCase();

  const hasDate =
    /\b(\d{1,2}[\/\-.]\d{1,2}[\/\-.]\d{2,4})\b/.test(s) ||
    /\b(ENERO|FEBRERO|MARZO|ABRIL|MAYO|JUNIO|JULIO|AGOSTO|SEPTIEMBRE|SETIEMBRE|OCTUBRE|NOVIEMBRE|DICIEMBRE)\b/i.test(s) ||
    /\b(LUNES|MARTES|MIERCOLES|MIÉRCOLES|JUEVES|VIERNES|SABADO|SÁBADO|DOMINGO)\b/i.test(s);

  const hasTime =
    /\b([01]?\d|2[0-3])[:.][0-5]\d\b/.test(s) ||
    /\b([01]?\d|2[0-3])\s?h\b/i.test(s);

  const hasPlace =
    /\b(CENTRO|SALON|SALÓN|TEATRO|AUDITORIO|PLAZA|BIBLIOTECA|PABELLON|PABELLÓN|CASA|RECINTO|POLIDEPORTIVO|PARQUE|PASEO)\b/i.test(s);

  const muniParts = ayto ? ayto.split(/\s+/).filter(p => p.length >= 4) : [];
  const hasMuni =
    /\bAYUNTAMIENTO\b/i.test(s) ||
    muniParts.some(p => new RegExp(`\\b${p}\\b`, 'i').test(s));

  return { date: hasDate, time: hasTime, place: hasPlace, muni: hasMuni };
}

function scoreText(t, flags) {
  const s = normText(t);
  const len = s.length;

  let score = 0;

  if (len >= 400) score += 35;
  else if (len >= 200) score += 25;
  else if (len >= 80) score += 15;
  else if (len >= 20) score += 5;

  if (flags.date)  score += 30;
  if (flags.time)  score += 15;
  if (flags.place) score += 10;
  if (flags.muni)  score += 10;

  return { len, score };
}

return $input.all().map(item => {
  const j = item.json || {};

  const status = str(j.STATUS).trim();
  const stage  = str(j.PROCESS_STAGE).trim();
  const aytoId = str(j.AYTO_ID).trim();

  // Textos RAW: DUAL OCR vs GVISION
  const tDualOCR = normText(j.OCR_TEXT_RAW || j.OCR_WIN_TEXT || '');
  const tGvision = normText(j.OCR_GVISION_RAW || '');

  const flagsDual = flagsFromText(tDualOCR, aytoId);
  const flagsGv   = flagsFromText(tGvision, aytoId);

  const scDual = scoreText(tDualOCR, flagsDual);
  const scGv   = scoreText(tGvision, flagsGv);

  // OCR_WINNER
  let OCR_WINNER = 'NONE';
  let OCR_TEXT_WIN = '';

  const margin = 5;

  if (scGv.len >= 20 && scGv.score >= (scDual.score + margin)) {
    OCR_WINNER = 'GVISION';
    OCR_TEXT_WIN = tGvision;
  } else if (scDual.len >= 20) {
    OCR_WINNER = 'DUAL_OCR';
    OCR_TEXT_WIN = tDualOCR;
  } else if (scGv.len >= 20) {
    OCR_WINNER = 'GVISION';
    OCR_TEXT_WIN = tGvision;
  } else {
    OCR_WINNER = 'NONE';
    OCR_TEXT_WIN = '';
  }

  const ocrLenForRules = Number(j.OCR_TEXT_LEN ?? scDual.len ?? 0) || 0;

  // CANDIDATOS_RESULT
  const fechaExtr = str(j.FECHA_EXTR).trim();
  let CANDIDATOS_RESULT = j.CANDIDATOS_RESULT ?? '';

  if (IN_PROCESS.has(status) || IN_PROCESS.has(stage)) {
    CANDIDATOS_RESULT = 'EN_PROCESO';
  }
  else if (
    status === 'OCR_EMPTY' ||
    (status === 'OCR_ERROR' && ocrLenForRules < 20)
  ) {
    CANDIDATOS_RESULT = 'DESCARTADO';
    OCR_WINNER = 'NONE';
    OCR_TEXT_WIN = '';
  }
  else if (!fechaExtr) {
    CANDIDATOS_RESULT = 'DUDOSO';
  }
  else if (OCR_WINNER !== 'NONE' && OCR_TEXT_WIN.length >= 80) {
    CANDIDATOS_RESULT = 'SELECCIONADO';
  }
  else {
    CANDIDATOS_RESULT = 'DUDOSO';
  }

  // PROCESS_STAGE final
  let PROCESS_STAGE = 'DESEMPATE_DONE';

  return {
    json: {
      ...j,
      OCR_WINNER,
      OCR_TEXT_WIN,
      OCR_WIN_SCORE_GVISION: String(scGv.score),
      OCR_WIN_SCORE_DUAL: String(scDual.score),
      OCR_WIN_FLAGS_GVISION: JSON.stringify(flagsGv),
      OCR_WIN_FLAGS_DUAL: JSON.stringify(flagsDual),
      CANDIDATOS_RESULT,
      PROCESS_STAGE
    }
  };
});

// ============================================================================
// OCR WINNER + CANDIDATOS_RESULT — TODO EN UN SOLO CODE (overwrite seguro)
// Reglas combinadas (2 bloques en 1):
// - EN_PROCESO: STATUS o PROCESS_STAGE ∈ {UPLOADED_TO_DROPBOX, PENDIENTE_DESCARGA}
// - DESCARTADO: STATUS=OCR_EMPTY OR (STATUS=OCR_ERROR && OCR_TEXT_LEN<20)
// - DUDOSO: si FECHA_EXTR vacío (manda)
// - SELECCIONADO: si hay FECHA_EXTR y OCR_WINNER != NONE y texto ganador >= 80
// ============================================================================

const IN_PROCESS = new Set(['UPLOADED_TO_DROPBOX', 'PENDIENTE_DESCARGA']);

function str(v) {
  return (v ?? '').toString();
}
function normText(t) {
  return str(t).replace(/\r/g, '').trim();
}

// flags "baratos" (sin LLM): fecha/hora/lugar/muni
function flagsFromText(t, aytoId) {
  const s = normText(t);
  const ayto = normText(aytoId).toUpperCase();

  const hasDate =
    /\b(\d{1,2}[\/\-\.]\d{1,2}[\/\-\.]\d{2,4})\b/.test(s) || // 28/12/2025
    /\b(ENERO|FEBRERO|MARZO|ABRIL|MAYO|JUNIO|JULIO|AGOSTO|SEPTIEMBRE|SETIEMBRE|OCTUBRE|NOVIEMBRE|DICIEMBRE)\b/i.test(s) ||
    /\b(LUNES|MARTES|MIERCOLES|MIÉRCOLES|JUEVES|VIERNES|SABADO|SÁBADO|DOMINGO)\b/i.test(s);

  const hasTime =
    /\b([01]?\d|2[0-3])[:\.][0-5]\d\b/.test(s) || // 12:00 / 12.00
    /\b([01]?\d|2[0-3])\s?h\b/i.test(s);        // 11h

  const hasPlace =
    /\b(CENTRO|SALON|SALÓN|TEATRO|AUDITORIO|PLAZA|BIBLIOTECA|PABELLON|PABELLÓN|CASA|RECINTO|POLIDEPORTIVO|PARQUE|PASEO)\b/i.test(s);

  // muni "dinámico" barato: si aparece parte del AYTO_ID
  const muniParts = ayto ? ayto.split(/\s+/).filter(p => p.length >= 4) : [];
  const hasMuni =
    /\bAYUNTAMIENTO\b/i.test(s) ||
    muniParts.some(p => new RegExp(`\\b${p}\\b`, 'i').test(s));

  return { date: hasDate, time: hasTime, place: hasPlace, muni: hasMuni };
}

function scoreText(t, flags) {
  const s = normText(t);
  const len = s.length;

  let score = 0;

  // peso por longitud (robusto)
  if (len >= 400) score += 35;
  else if (len >= 200) score += 25;
  else if (len >= 80) score += 15;
  else if (len >= 20) score += 5;

  // peso por señales
  if (flags.date)  score += 30;
  if (flags.time)  score += 15;
  if (flags.place) score += 10;
  if (flags.muni)  score += 10;

  return { len, score };
}

return $input.all().map(item => {
  const j = item.json || {};

  const status = str(j.STATUS).trim();
  const stage  = str(j.PROCESS_STAGE).trim();
  const aytoId = str(j.AYTO_ID).trim();

  // textos RAW (si no vienen, se quedan vacíos)
  const tSpace = normText(j.OCR_TEXT_RAW);
  const tGv    = normText(j.OCR_GVISION_RAW);

  // scoring
  const flagsSpace = flagsFromText(tSpace, aytoId);
  const flagsGv    = flagsFromText(tGv, aytoId);

  const scSpace = scoreText(tSpace, flagsSpace);
  const scGv    = scoreText(tGv, flagsGv);

  // ------------------------------------------------------------
  // 1) OCR_WINNER (overwrite)
  // ------------------------------------------------------------
  let OCR_WINNER = 'NONE';
  let OCR_TEXT_WIN = '';

  const margin = 5;

  // Preferimos el que tenga "mejor pinta" + mínimo texto
  if (scGv.len >= 20 && scGv.score >= (scSpace.score + margin)) {
    OCR_WINNER = 'GVISION';
    OCR_TEXT_WIN = tGv;
  } else if (scSpace.len >= 20) {
    OCR_WINNER = 'OCR_SPACE';
    OCR_TEXT_WIN = tSpace;
  } else if (scGv.len >= 20) {
    OCR_WINNER = 'GVISION';
    OCR_TEXT_WIN = tGv;
  } else {
    OCR_WINNER = 'NONE';
    OCR_TEXT_WIN = '';
  }

  // Para reglas de DESCARTADO por OCR_ERROR usamos OCR_TEXT_LEN (o si no, len calculada de OCR_SPACE)
  const ocrLenForRules = Number(j.OCR_TEXT_LEN ?? scSpace.len ?? 0) || 0;

  // ------------------------------------------------------------
  // 2) CANDIDATOS_RESULT (2 reglas combinadas)
  // ------------------------------------------------------------
  const fechaExtr = str(j.FECHA_EXTR).trim();
  let CANDIDATOS_RESULT = j.CANDIDATOS_RESULT ?? '';

  // 1) EN_PROCESO manda
  if (IN_PROCESS.has(status) || IN_PROCESS.has(stage)) {
    CANDIDATOS_RESULT = 'EN_PROCESO';
  }
  // 2) DESCARTADO SOLO por estados OCR malos (no por winner)
  else if (
    status === 'OCR_EMPTY' ||
    (status === 'OCR_ERROR' && ocrLenForRules < 20)
  ) {
    CANDIDATOS_RESULT = 'DESCARTADO';
    OCR_WINNER = 'NONE';
    OCR_TEXT_WIN = '';
  }
  // 3) sin fecha => DUDOSO (manda)
  else if (!fechaExtr) {
    CANDIDATOS_RESULT = 'DUDOSO';
  }
  // 4) con fecha + winner + texto mínimo => SELECCIONADO
  else if (OCR_WINNER !== 'NONE' && OCR_TEXT_WIN.length >= 80) {
    CANDIDATOS_RESULT = 'SELECCIONADO';
  }
  // 5) resto => DUDOSO
  else {
    CANDIDATOS_RESULT = 'DUDOSO';
  }

  return {
    json: {
      ...j,

      // winner completo
      OCR_WINNER,
      OCR_TEXT_WIN,
      OCR_WIN_SCORE_GVISION: String(scGv.score),
      OCR_WIN_SCORE_OCR_SPACE: String(scSpace.score),
      OCR_WIN_FLAGS_GVISION: JSON.stringify(flagsGv),
      OCR_WIN_FLAGS_OCR_SPACE: JSON.stringify(flagsSpace),

      // candidatos
      CANDIDATOS_RESULT,
    }
  };
});

