let parsed = {};
let llmError = '';

try {
  // Obtener contenido del LLM
  let content = null;

  // Formato OpenAI node con Simplify Output
  if (llmResponse.message?.content) {
    content = llmResponse.message.content;
  }
  // Formato array de choices (HTTP Request)
  else if (llmResponse.choices?.[0]?.message?.content) {
    content = llmResponse.choices[0].message.content;
  }
  // Content directo (algunas versiones del nodo)
  else if (llmResponse.content) {
    content = llmResponse.content;
  }
  // Respuesta directa ya es el objeto JSON
  else if (llmResponse.TITULO !== undefined || llmResponse.ES_EVENTO !== undefined) {
    content = llmResponse;
  }

  // Verificar tipo de content y parsear si es necesario
  if (content && typeof content === 'object') {
    // Ya es objeto JSON, usarlo directamente
    parsed = content;
    console.log('LLM response: Ya es objeto JSON');
  } else if (typeof content === 'string') {
    // Es string, limpiar y parsear
    content = content.replace(/```json\n?/gi, '').replace(/\n?```/g, '').trim();
    parsed = JSON.parse(content);
    console.log('LLM response: Parseado desde string');
  } else {
    throw new Error('No se pudo obtener contenido valido del LLM');
  }

} catch (e) {
  llmError = `Parse error: ${e.message}`;
  console.log(`ERROR parsing LLM response: ${e.message}`);
  console.log('Raw response keys:', Object.keys($input.first().json));
}

// Helper para valor limpio
function clean(val) {
  return String(val || '').trim();
}

// Normalizar AYTO / AYTO. / AYUNT. -> AYUNTAMIENTO
function normalizeAyuntamiento(str) {
  if (!str) return '';
  let s = String(str || '').trim().toUpperCase();
  s = s
    .replace(/\u00c1/g, 'A').replace(/\u00c9/g, 'E').replace(/\u00cd/g, 'I').replace(/\u00d3/g, 'O').replace(/\u00da/g, 'U')
    .replace(/\u00c0/g, 'A').replace(/\u00c8/g, 'E').replace(/\u00cc/g, 'I').replace(/\u00d2/g, 'O').replace(/\u00d9/g, 'U')
    .replace(/\u00c4/g, 'A').replace(/\u00cb/g, 'E').replace(/\u00cf/g, 'I').replace(/\u00d6/g, 'O').replace(/\u00dc/g, 'U')
    .replace(/\u00c2/g, 'A').replace(/\u00ca/g, 'E').replace(/\u00ce/g, 'I').replace(/\u00d4/g, 'O').replace(/\u00db/g, 'U')
    .replace(/\u00c7/g, 'C');
  s = s.replace(/\bAYTO\.?\b/g, 'AYUNTAMIENTO');
  s = s.replace(/\bAYUNT\.?\b/g, 'AYUNTAMIENTO');
  return s.replace(/\s+/g, ' ').trim();
}

