if (v(postData.NOMBRE_EVENTO)) camposPost.push(`NOMBRE_EVENTO: ${v(postData.NOMBRE_EVENTO)}`);
if (v(postData.FECHA_EVENTO)) camposPost.push(`FECHA_EVENTO: ${v(postData.FECHA_EVENTO)}`);
if (v(postData.HORA_EVENTO)) camposPost.push(`HORA_EVENTO: ${v(postData.HORA_EVENTO)}`);
if (v(postData.LUGAR_EVENTO)) camposPost.push(`LUGAR_EVENTO: ${v(postData.LUGAR_EVENTO)}`);
if (v(postData.PRECIO_EVENTO)) camposPost.push(`PRECIO_EVENTO: ${v(postData.PRECIO_EVENTO)}`);
if (v(postData.TIPO_EVENTO)) camposPost.push(`TIPO_EVENTO: ${v(postData.TIPO_EVENTO)}`);
if (v(postData.AYTO_ID)) camposPost.push(`AYTO_ID: ${v(postData.AYTO_ID)}`);
if (v(postData.POST_URL)) camposPost.push(`POST_URL: ${v(postData.POST_URL)}`);
if (v(postData.FECHA_PUBLICACION)) camposPost.push(`FECHA_PUBLICACION: ${v(postData.FECHA_PUBLICACION)}`);
if (v(postData.HORA_PUBLICACION)) camposPost.push(`HORA_PUBLICACION: ${v(postData.HORA_PUBLICACION)}`);

const aytoId = v(postData.AYTO_ID) || '';
const municipioInferido = aytoId.replace(/^ayto_fb_/i, '').replace(/_/g, ' ');

const prompt = `Analiza el contenido de un post de Facebook de un ayuntamiento y extrae datos estructurados del EVENTO.

=== DATOS DEL POST ===
${camposPost.length > 0 ? camposPost.join('\n') : '(sin datos)'}

=== ETIQUETAS DISPONIBLES (usar solo estas) ===
${etiquetas || '(sin etiquetas)'}

=== INSTRUCCIONES ===
Extrae los siguientes campos del EVENTO. Si no hay informacion clara, deja vacio.

- TODOS los campos de salida en MAYUSCULAS y SIN ACENTOS, pero respetando \u00d1
- TITULO: nombre del evento (obligatorio si es evento)
- FECHA: formato DD/MM/YYYY
- HORA: formato HH:MM
- PRECIO: numero con "\u20AC" si aparece; si dice gratis/gratuito -> "GRATUITO"; si no hay info -> vacio
- LOCAL: nombre del lugar/sala donde se celebra
- LOCALIDAD: localidad/barrio (si no aparece, usar "${municipioInferido}")
- MUNICIPIO: municipio (si no aparece, usar "${municipioInferido}")
- TIPO_EVENTO: elegir UNA de las etiquetas disponibles que mejor describa el tipo
- ETIQUETAS: una o mas etiquetas separadas por coma
- ORGANIZADOR: aplicar estas reglas:
  * Si NO aparece nadie organizando = "AYUNTAMIENTO"
  * Si solo aparece DIPUTACION organizando = "DIPUTACION"
  * Si organiza un tercero (ej. DANZAITALIANA) = ORGANIZADOR=tercero
  * Si no esta claro si es DIPUTACION = "REVISION_HUMANA_DIPUTACION"
- COLABORADOR: aplicar estas reglas:
  * Si ORGANIZADOR=AYUNTAMIENTO y aparece DIPUTACION = "DIPUTACION"
  * Si ORGANIZADOR=AYUNTAMIENTO y aparece un tercero = nombre del tercero
  * Si ORGANIZADOR=DIPUTACION y aparece el Ayuntamiento = "AYUNTAMIENTO"
  * Si ORGANIZADOR=tercero y aparece AYUNTAMIENTO = "AYUNTAMIENTO"
- INSCRIPCION: "SI" o "NO"
- VENTA_ENTRADAS: "SI", "NO", o URL de compra si aparece
- ES_EVENTO: "SI" si claramente es un evento con fecha, "NO" si es noticia/informacion general

Responde SOLO en formato JSON valido con estos campos exactos. Sin explicaciones adicionales.`;

return [{
  json: {
    IDEMPOT_KEY: postData.IDEMPOT_KEY,
    prompt,
    aytoId,
    _postData: postData
  }
}];

// ========================================
// Parsear respuesta LLM y preparar campos FINAL
// ========================================

const llmResponse = $input.first().json;

// ctx seguro (usa el nombre REAL del nodo)
let ctx = { IDEMPOT_KEY: '', aytoId: '', _postData: {} };
try {
  const items = $items('3. Prepare LLM Prompt') || [];
  if (items[$itemIndex]) ctx = items[$itemIndex].json;
} catch (e) {
  if ($json._postData || $json.IDEMPOT_KEY) ctx = $json;
}

let parsed = {};
let llmError = '';

try {
  let content = null;

  if (llmResponse.message?.content) {
    content = llmResponse.message.content;
  } else if (llmResponse.choices?.[0]?.message?.content) {
    content = llmResponse.choices[0].message.content;
  } else if (llmResponse.content) {
    content = llmResponse.content;
  } else if (llmResponse.TITULO !== undefined || llmResponse.ES_EVENTO !== undefined) {
    content = llmResponse;
  }

  if (content && typeof content === 'object') {
    parsed = content;
  } else if (typeof content === 'string') {
    content = content.replace(/```json\\n?/gi, '').replace(/\\n?```/g, '').trim();
    parsed = JSON.parse(content);
  } else {
    throw new Error('No se pudo obtener contenido valido del LLM');
  }

} catch (e) {
  llmError = `Parse error: ${e.message}`;
  console.log(`ERROR parsing LLM response: ${e.message}`);
}

function clean(val) {
  return String(val || '').trim();
}

function toUpperNoAccentsKeepNY(val) {
  const s = String(val || '').trim().toUpperCase();
  return s
    .replace(/\u00c1/g, 'A').replace(/\u00c9/g, 'E').replace(/\u00cd/g, 'I').replace(/\u00d3/g, 'O').replace(/\u00da/g, 'U')
    .replace(/\u00c0/g, 'A').replace(/\u00c8/g, 'E').replace(/\u00cc/g, 'I').replace(/\u00d2/g, 'O').replace(/\u00d9/g, 'U')
    .replace(/\u00c4/g, 'A').replace(/\u00cb/g, 'E').replace(/\u00cf/g, 'I').replace(/\u00d6/g, 'O').replace(/\u00dc/g, 'U')
    .replace(/\u00c2/g, 'A').replace(/\u00ca/g, 'E').replace(/\u00ce/g, 'I').replace(/\u00d4/g, 'O').replace(/\u00db/g, 'U')
    .replace(/\u00c7/g, 'C');
}

function normPrecio(val) {
  const s = String(val || '').trim();
  if (!s) return '';
  const upper = toUpperNoAccentsKeepNY(s);
  if (upper.includes('GRATIS') || upper.includes('GRATUITO')) return 'GRATUITO';
  if (/\\d/.test(upper) && !upper.includes('\u20AC')) return `${upper} \u20AC`;
  return upper;
}

const observaciones = {
  postUrl: ctx._postData?.POST_URL || '',
  llmResponse: parsed,
  llmError: llmError || undefined
};

const municipioAyto = String(ctx.aytoId || '').replace(/^ayto_fb_/i, '').replace(/_/g, ' ').trim();
const municipioFinal = clean(parsed.MUNICIPIO) || municipioAyto;
const localidadFinal = clean(parsed.LOCALIDAD) || municipioAyto;

const esEvento = toUpperNoAccentsKeepNY(parsed.ES_EVENTO) || 'SI';
const candidatosFinal = llmError
  ? 'DUDOSO'
  : (esEvento === 'NO' ? 'DESCARTADO' : 'SELECCIONADO');

const idempotKey =
  ctx.IDEMPOT_KEY ||
  ctx._postData?.IDEMPOT_KEY ||
  $json.IDEMPOT_KEY ||
  '';

// NORMALIZAR AYTO / AYTO. / AYUNT.
function normalizeAyuntamiento(str) {
  if (!str) return '';
  let s = toUpperNoAccentsKeepNY(str);
  s = s.replace(/\bAYTO\.?\b/g, 'AYUNTAMIENTO');
  s = s.replace(/\bAYUNT\.?\b/g, 'AYUNTAMIENTO');
  return s.replace(/\s+/g, ' ').trim();
}

// ORGANIZADOR con municipio si contiene AYUNTAMIENTO
let organizadorFinal = normalizeAyuntamiento(parsed.ORGANIZADOR) || 'AYUNTAMIENTO';
const muniUpper = toUpperNoAccentsKeepNY(municipioFinal);
const orgHasAyto = organizadorFinal.includes('AYUNTAMIENTO');
const orgHasMuni = muniUpper && organizadorFinal.includes(muniUpper);

if (orgHasAyto && !orgHasMuni) {
  organizadorFinal = muniUpper ? `AYUNTAMIENTO ${muniUpper}` : 'AYUNTAMIENTO';
}

const result = {
  IDEMPOT_KEY: idempotKey,

  TITULO_FINAL_EVENTO: toUpperNoAccentsKeepNY(parsed.TITULO),
  FECHA_FINAL_EVENTO: clean(parsed.FECHA),
  HORA_FINAL_EVENTO: clean(parsed.HORA),
  PRECIO_FINAL_EVENTO: normPrecio(parsed.PRECIO),
  LOCAL_FINAL_EVENTO: toUpperNoAccentsKeepNY(parsed.LOCAL),
  LOCALIDAD_FINAL_EVENTO: toUpperNoAccentsKeepNY(localidadFinal),
  MUNICIPIO_FINAL_EVENTO: toUpperNoAccentsKeepNY(municipioFinal),
  TIPO_FINAL_EVENTO: toUpperNoAccentsKeepNY(parsed.TIPO_EVENTO),
  ETIQUETAS_FINAL_EVENTO: toUpperNoAccentsKeepNY(parsed.ETIQUETAS),
  ORGANIZADOR_FINAL_EVENTO: organizadorFinal,
  COLABORADOR_FINAL_EVENTO: normalizeAyuntamiento(parsed.COLABORADOR),
  INSCRIPCION_FINAL_EVENTO: toUpperNoAccentsKeepNY(parsed.INSCRIPCION) || 'NO',
  VENTA_ENTRADAS_FINAL_EVENTO: toUpperNoAccentsKeepNY(parsed.VENTA_ENTRADAS) || 'NO',
  OBSERVACIONES_DRAMATICOS_FINAL_EVENTO: JSON.stringify(observaciones),

  MEDIA_OCR_STATUS: $json.MEDIA_OCR_STATUS || '',
  MEDIA_OCR_COUNT: $json.MEDIA_OCR_COUNT || '',

  LLM_AT: new Date().toISOString(),
  LLM_STATUS: llmError ? 'ERROR' : (esEvento === 'NO' ? 'NO_EVENTO' : 'EXTRACTED'),
  ES_EVENTO_LLM: esEvento,

  CANDIDATOS_RESULT_FINAL: candidatosFinal
};

return [{ json: result }];

// ========================================
// Parsear respuesta LLM y preparar campos FINAL
// ========================================

const llmResponse = $input.first().json;
const ctx = $('5. Prepare LLM Prompt').item.json;
const mediaItems = ctx._mediaItems || [];

let parsed = {};
let llmError = '';

try {
  // Obtener contenido del LLM
  let content = null;

  // Formato OpenAI node con Simplify Output
  if (llmResponse.message?.content) {
    content = llmResponse.message.content;
  }
  // Formato array de choices (HTTP Request)
  else if (llmResponse.choices?.[0]?.message?.content) {
    content = llmResponse.choices[0].message.content;
  }
  // Content directo (algunas versiones del nodo)
  else if (llmResponse.content) {
    content = llmResponse.content;
  }
  // Respuesta directa ya es el objeto JSON
  else if (llmResponse.TITULO !== undefined || llmResponse.ES_EVENTO !== undefined) {
    content = llmResponse;
  }

  // Verificar tipo de content y parsear si es necesario
  if (content && typeof content === 'object') {
    // Ya es objeto JSON, usarlo directamente
    parsed = content;
    console.log('LLM response: Ya es objeto JSON');
  } else if (typeof content === 'string') {
    // Es string, limpiar y parsear
    content = content.replace(/```json\n?/gi, '').replace(/\n?```/g, '').trim();
    parsed = JSON.parse(content);
    console.log('LLM response: Parseado desde string');
  } else {
    throw new Error('No se pudo obtener contenido valido del LLM');
  }

} catch (e) {
  llmError = `Parse error: ${e.message}`;
  console.log(`ERROR parsing LLM response: ${e.message}`);
  console.log('Raw response keys:', Object.keys($input.first().json));
}

// Helper para valor limpio
function clean(val) {
  return String(val || '').trim();
}

// Determinar mejor CANDIDATOS_RESULT de los media items
const statusPriority = { 'SELECCIONADO': 3, 'DUDOSO': 2, 'DESCARTADO': 1, 'EN_PROCESO': 0 };
const bestStatus = mediaItems.reduce((best, m) => {
  const s = m.CANDIDATOS_RESULT || '';
  return (statusPriority[s] || 0) > (statusPriority[best] || 0) ? s : best;
}, '');

// Construir objeto observaciones
const observaciones = {
  urlsImagenes: JSON.parse(ctx.urlsImagenes || '[]'),
  mediaCount: ctx.mediaCount,
  llmResponse: parsed,
  llmError: llmError || undefined
};

// Construir resultado
const result = {
  IDEMPOT_KEY: ctx.IDEMPOT_KEY,

  // Campos FINAL_EVENTO
  TITULO_FINAL_EVENTO: clean(parsed.TITULO),
  FECHA_FINAL_EVENTO: clean(parsed.FECHA),
  HORA_FINAL_EVENTO: clean(parsed.HORA),
  PRECIO_FINAL_EVENTO: clean(parsed.PRECIO),
  LOCAL_FINAL_EVENTO: clean(parsed.LOCAL),
  LOCALIDAD_FINAL_EVENTO: clean(parsed.LOCALIDAD),
  MUNICIPIO_FINAL_EVENTO: clean(parsed.MUNICIPIO),
  TIPO_FINAL_EVENTO: clean(parsed.TIPO_EVENTO),
  ETIQUETAS_FINAL_EVENTO: clean(parsed.ETIQUETAS),
  ORGANIZADOR_FINAL_EVENTO: clean(parsed.ORGANIZADOR) || 'AYUNTAMIENTO',
  COLABORADOR_FINAL_EVENTO: clean(parsed.COLABORADOR),
  INSCRIPCION_FINAL_EVENTO: clean(parsed.INSCRIPCION) || 'NO',
  VENTA_ENTRADAS_FINAL_EVENTO: clean(parsed.VENTA_ENTRADAS) || 'NO',
  OBSERVACIONES_DRAMATICOS_FINAL_EVENTO: JSON.stringify(observaciones),

  // Metadata
  MEDIA_OCR_STATUS: bestStatus,
  MEDIA_OCR_COUNT: String(mediaItems.length),
  LLM_AT: new Date().toISOString(),
  LLM_STATUS: llmError ? 'ERROR' : (clean(parsed.ES_EVENTO) === 'NO' ? 'NO_EVENTO' : 'EXTRACTED'),
  ES_EVENTO_LLM: clean(parsed.ES_EVENTO) || 'SI'
};

console.log(`Parsed LLM for ${ctx.IDEMPOT_KEY}: STATUS=${result.LLM_STATUS}`);
if (result.TITULO_FINAL_EVENTO) console.log(`  TITULO: ${result.TITULO_FINAL_EVENTO}`);
if (result.FECHA_FINAL_EVENTO) console.log(`  FECHA: ${result.FECHA_FINAL_EVENTO}`);

return [{ json: result }];

