const rows = items.map(i => i.json);

const testMode = $items('Set: Test1')[0].json.TEST_MODE === true;
const testAyto = String($items('Set: Test1')[0].json.TEST_AYTO_ID || '').trim();

function asBool(v) {
  const s = String(v ?? '').trim().toUpperCase();
  if (['TRUE', 'VERDADERO', '1', 'SI', 'YES'].includes(s)) return true;
  if (['FALSE', 'FALSO', '0', 'NO'].includes(s)) return false;
  return Boolean(v);
}

const out = [];
for (const r of rows) {
  if (!asBool(r.ACTIVO)) continue;
  if (testMode && testAyto && String(r.AYTO_ID_TECNICO || '').trim() !== testAyto) continue;
  out.push({ json: r });
}
return out;

const raw = $input.first().json;
const text = raw.body ?? raw.data ?? raw;

const s = String(text || '').trim();
if (!s) return [];

// Caso JSON array: empieza por [
if (s.startsWith('[')) {
  const arr = JSON.parse(s);
  return (arr || []).map(x => ({ json: x }));
}

// Caso NDJSON: muchas líneas { }
const lines = s.split('\n').map(l => l.trim()).filter(Boolean);
return lines.map(l => ({ json: JSON.parse(l) }));

// MAPFB_POST_RAW — VERSION FULL COMPAT (FASE1) — ADAPTADA A TU JSON NUEVO (attachments[])
// - Ñ intacta, mayúsculas, sin acentos
// - Mantiene campos que tu Sheet ya espera (placeholders incluidos)
// - Añade PAGE/USER RAW
// - Calcula IMG_URLS / VIDEO_URLS / THUMB_URLS y flags de media
// - NO hace FASE2 (solo mapeo)

// =========================
// Helpers (igual estilo)
// =========================
function fromCamelCase(str) {
  if (!str) return '';
  return String(str)
    .replace(/([a-z])([A-Z])/g, '$1 $2')
    .replace(/([A-Z])([A-Z][a-z])/g, '$1 $2');
}

function cleanAytoName(str) {
  if (!str) return '';
  return String(str)
    .replace(/^AYUNTAMIENTO DE\s+/i, '')
    .replace(/^AYTO\.?\s+DE\s+/i, '')
    .replace(/^AYTO\.?\s+/i, '');
}

// ✅ Normaliza SIN cargarse la Ñ
function normalize(str) {
  if (!str) return '';
  const s = String(str || '');

  const protectedÑ = s
    .replace(/ñ/g, '__ENYE_MIN__')
    .replace(/Ñ/g, '__ENYE_MAY__');

  const noAccents = protectedÑ
    .toUpperCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');

  const restored = noAccents
    .replace(/__ENYE_MIN__/g, 'Ñ')
    .replace(/__ENYE_MAY__/g, 'Ñ');

  return restored
    .replace(/[^A-Z0-9 Ñ/.-]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function formatDateES(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  if (isNaN(d)) return '';
  const dd = String(d.getDate()).padStart(2, '0');
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const yyyy = d.getFullYear();
  return `${dd}/${mm}/${yyyy}`;
}

function formatTimeES(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  if (isNaN(d)) return '';
  return `${String(d.getHours()).padStart(2, '0')}:${String(d.getMinutes()).padStart(2, '0')}`;
}

function isReelUrl(url) {
  const u = String(url || '').toLowerCase();
  return u.includes('/reel/') || u.includes('/reels/') || u.includes('reel');
}

function safeJsonStringify(obj) {
  try { return JSON.stringify(obj ?? null); } catch (e) { return ''; }
}

function uniq(arr) {
  const out = [];
  const seen = new Set();
  for (const v of (arr || [])) {
    const s = String(v || '').trim();
    if (!s) continue;
    if (seen.has(s)) continue;
    seen.add(s);
    out.push(s);
  }
  return out;
}

// =========================
// MAIN
// =========================
return items.map((item) => {
  const p = item.json || {};

  // ---- RAW trazabilidad PAGE/USER (sin inventar) ----
  const pageNameRaw = (p.page_name !== null && p.page_name !== undefined) ? String(p.page_name) : '';
  const userNameRaw = (p.user_username_raw !== null && p.user_username_raw !== undefined) ? String(p.user_username_raw) : '';
  const pageIdRaw   = (p.profile_id !== null && p.profile_id !== undefined) ? String(p.profile_id) : '';
  const userIdRaw   = (p.profile_id !== null && p.profile_id !== undefined) ? String(p.profile_id) : '';
  const pageUrlRaw  = (p.page_url !== null && p.page_url !== undefined) ? String(p.page_url) : '';

  // MUNICIPIO: 1º user_username_raw, 2º page_name
  let municipioRaw = '';
  if (userNameRaw) {
    municipioRaw = cleanAytoName(userNameRaw);
  } else {
    municipioRaw = fromCamelCase(pageNameRaw);
  }

  const MUNICIPIO = normalize(municipioRaw);
  const LOCALIDAD = MUNICIPIO; // FASE 1
  const PROVINCIA = 'ALMERIA';

  const postUrl = p.url || '';
  const postId = (p.post_id !== null && p.post_id !== undefined) ? String(p.post_id) : '';

  // Texto
  const textoPostRaw = (p.content !== null && p.content !== undefined) ? String(p.content) : '';
  const tieneTexto = (textoPostRaw.trim().length > 0) ? 'SI' : 'NO';
  const TEXTO_LEN = textoPostRaw.length;

  // Media (nuevo: attachments[])
  const mediaArr = Array.isArray(p.attachments) ? p.attachments : [];
  const MEDIA_COUNT_TOTAL = mediaArr.length;

  const numFotos = mediaArr.filter(m => m && String(m.type || '').toLowerCase() === 'photo').length;

  // Reel: por post_type o por URL
  const postTypeRaw = String(p.post_type || '').toUpperCase(); // "POST" / "REEL" o vacío
  const esReel = (postTypeRaw === 'REEL' || isReelUrl(postUrl)) ? 'SI' : 'NO';

  // Tiene video: por attachments o por reel
  const tieneVideo = (
    mediaArr.some(m => m && (
      String(m.type || '').toLowerCase() === 'video' ||
      !!m.video_url
    )) ||
    esReel === 'SI'
  ) ? 'SI' : 'NO';

  const numVideos = mediaArr.filter(m => m && (
    String(m.type || '').toLowerCase() === 'video' || !!m.video_url
  )).length;

  const MEDIA_HAS_PHOTO = (numFotos > 0) ? 'SI' : 'NO';
  const MEDIA_HAS_VIDEO = (numVideos > 0 || tieneVideo === 'SI') ? 'SI' : 'NO';

  // POST_TYPE compatible
  const POST_TYPE = (esReel === 'SI') ? 'REEL' : 'POST';

  // URLs de media (mezcla útil)
  const mediaUrls = uniq(
    mediaArr.flatMap(m => {
      if (!m) return [];
      return [
        m.url,
        m.video_url,
        m.thumbnail_url,
        m.attachment_url
      ];
    })
  );

  // IMG_URLS / VIDEO_URLS / THUMB_URLS (separados)
  const imgUrls = uniq(
    mediaArr
      .filter(m => m && String(m.type || '').toLowerCase() === 'photo')
      .map(m => m.url || m.thumbnail_url || '')
  );

  const videoUrls = uniq(
    mediaArr
      .filter(m => m && (String(m.type || '').toLowerCase() === 'video' || !!m.video_url))
      .map(m => m.video_url || m.attachment_url || m.url || '')
  );

  const thumbUrls = uniq(
    mediaArr
      .map(m => m && (m.thumbnail_url || (String(m.type || '').toLowerCase() === 'video' ? m.url : '') || '') )
  );

  const tieneMedia = (mediaArr.length > 0) ? 'SI' : 'NO';

  const nowIso = new Date().toISOString();

  // Fecha publicación (ISO)
  const timeIso = (p.date_posted !== null && p.date_posted !== undefined) ? String(p.date_posted) : '';

  return {
    json: {
      // ---- ids / trazabilidad ----
      IDEMPOT_KEY: `${MUNICIPIO}_${postId}`,
      AYTO_ID: MUNICIPIO,

      POST_ID: postId,
      POST_URL: postUrl,

      FECHA_PUBLICACION: formatDateES(timeIso),
      HORA_PUBLICACION: formatTimeES(timeIso),

      // ---- texto ----
      TIENE_TEXTO: tieneTexto,
      TEXTO_POST: normalize(textoPostRaw),
      TEXTO_POST_RAW: textoPostRaw,
      TEXTO_LEN: TEXTO_LEN, // ✅ mantenido

      // ---- media / compat ----
      NUM_IMAGENES: numFotos,
      TIENE_VIDEO: tieneVideo,
      MEDIA_URLS: mediaUrls.join(' | '),

      IMG_URLS: imgUrls.join(' | '),
      VIDEO_URLS: videoUrls.join(' | '),
      THUMB_URLS: thumbUrls.join(' | '),

      MEDIA_COUNT_TOTAL: MEDIA_COUNT_TOTAL,
      MEDIA_HAS_PHOTO: MEDIA_HAS_PHOTO,
      MEDIA_HAS_VIDEO: MEDIA_HAS_VIDEO,

      POST_TYPE: POST_TYPE,
